package main

import (
	"strings"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

type previewLoadedMsg struct {
	targetID string
	text     string
	err      error
}

type snapshotTickMsg struct{}

type pickerModel struct {
	view          string
	query         string
	allItems      []PickerItem
	visible       []PickerItem
	selectedID    string
	snapshot      HerdrSessionSnapshot
	history       FocusHistory
	spaceRows     [][]string
	agentRows     [][]string
	width         int
	height        int
	previewText   string
	previewErr    string
	previewTarget string
	pollEvery     time.Duration
	launch        pickerLaunchContext
}

func newPickerModel(view string, snapshot HerdrSessionSnapshot, history FocusHistory, spaceRows, agentRows [][]string, pollEvery time.Duration) pickerModel {
	history = pruneFocusHistory(history, snapshot)
	items := BuildPickerItems(view, snapshot, history, spaceRows, agentRows)
	launch := pickerLaunchFromEnv(snapshot, history)
	model := pickerModel{
		view:      view,
		allItems:  items,
		snapshot:  snapshot,
		history:   history,
		spaceRows: spaceRows,
		agentRows: agentRows,
		pollEvery: pollEvery,
		launch:    launch,
	}
	model.visible = FilterPickerItems(items, "")
	model.selectedID = PreselectPickerItemID(view, model.visible, history, launch)
	return model
}

func (m pickerModel) Init() tea.Cmd {
	return tea.Batch(m.previewCmd(), tickSnapshot(m.pollEvery))
}

func tickSnapshot(every time.Duration) tea.Cmd {
	return tea.Tick(every, func(time.Time) tea.Msg { return snapshotTickMsg{} })
}

func (m pickerModel) previewCmd() tea.Cmd {
	if !m.wideEnoughForPreview() {
		return nil
	}
	item, ok := m.selectedItem()
	if !ok || item.PreviewPane == "" {
		return nil
	}
	targetID := item.ID
	paneID := item.PreviewPane
	return func() tea.Msg {
		result, err := ReadHerdrPaneVisibleANSI(paneID)
		if err != nil {
			return previewLoadedMsg{targetID: targetID, err: err}
		}
		return previewLoadedMsg{targetID: targetID, text: AllowVisiblePreviewANSI(result.Text)}
	}
}

func (m pickerModel) wideEnoughForPreview() bool {
	return m.width >= WidePopupPreviewMinColumns
}

func (m pickerModel) selectedItem() (PickerItem, bool) {
	if m.selectedID == "" {
		return PickerItem{}, false
	}
	for _, item := range m.visible {
		if item.ID == m.selectedID {
			return item, true
		}
	}
	return PickerItem{}, false
}

func (m pickerModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		wasWide := m.wideEnoughForPreview()
		m.width = msg.Width
		m.height = msg.Height
		nowWide := m.wideEnoughForPreview()
		if !nowWide {
			m.previewText = ""
			m.previewErr = ""
			m.previewTarget = ""
			return m, nil
		}
		if nowWide && !wasWide {
			return m, m.previewCmd()
		}
		return m, nil
	case snapshotTickMsg:
		snapshot, err := LoadHerdrSessionSnapshot()
		if err == nil {
			m.snapshot = snapshot
			m.history = pruneFocusHistory(m.history, snapshot)
			m.rebuildItemsKeepOrder()
		}
		cmds := []tea.Cmd{tickSnapshot(m.pollEvery)}
		if m.wideEnoughForPreview() {
			cmds = append(cmds, m.previewCmd())
		}
		return m, tea.Batch(cmds...)
	case previewLoadedMsg:
		if msg.targetID != m.selectedID || !m.wideEnoughForPreview() {
			return m, nil
		}
		m.previewTarget = msg.targetID
		if msg.err != nil {
			m.previewErr = msg.err.Error()
			m.previewText = ""
			return m, nil
		}
		m.previewErr = ""
		m.previewText = msg.text
		return m, nil
	case pickerAcceptedMsg:
		return m, tea.Quit
	case tea.KeyMsg:
		switch msg.Type {
		case tea.KeyCtrlC, tea.KeyEsc:
			return m, tea.Quit
		case tea.KeyEnter:
			return m, m.acceptCmd()
		case tea.KeyUp:
			m.moveSelection(-1)
			return m, m.resetPreview()
		case tea.KeyDown:
			m.moveSelection(1)
			return m, m.resetPreview()
		case tea.KeyTab:
			m.cycleView(1)
			return m, m.resetPreview()
		case tea.KeyShiftTab:
			m.cycleView(-1)
			return m, m.resetPreview()
		case tea.KeyBackspace:
			if len(m.query) > 0 {
				r := []rune(m.query)
				m.query = string(r[:len(r)-1])
				m.applyQuery()
			}
			return m, m.resetPreview()
		default:
			if msg.Type == tea.KeyRunes {
				m.query += string(msg.Runes)
				m.applyQuery()
				return m, m.resetPreview()
			}
		}
	}
	return m, nil
}

func (m *pickerModel) resetPreview() tea.Cmd {
	m.previewText = ""
	m.previewErr = ""
	m.previewTarget = ""
	return m.previewCmd()
}

func (m *pickerModel) applyQuery() {
	m.visible = FilterPickerItems(m.allItems, m.query)
	if pickerItemByID(m.visible, m.selectedID) {
		return
	}
	m.selectedID = ""
	if m.query == "" {
		m.selectedID = PreselectPickerItemID(m.view, m.visible, m.history, m.launch)
	}
}

func (m *pickerModel) rebuildItemsKeepOrder() {
	fresh := BuildPickerItems(m.view, m.snapshot, m.history, m.spaceRows, m.agentRows)
	byID := map[string]PickerItem{}
	for _, item := range fresh {
		byID[item.ID] = item
	}
	var kept []PickerItem
	seen := map[string]bool{}
	for _, item := range m.allItems {
		if next, ok := byID[item.ID]; ok {
			kept = append(kept, next)
			seen[item.ID] = true
		}
	}
	for _, item := range fresh {
		if !seen[item.ID] {
			kept = append(kept, item)
		}
	}
	m.allItems = kept
	if m.query == "" {
		m.visible = kept
	} else {
		var visible []PickerItem
		for _, item := range m.visible {
			if next, ok := byID[item.ID]; ok {
				visible = append(visible, next)
			}
		}
		m.visible = visible
	}
	if m.selectedID != "" && !pickerItemByID(m.visible, m.selectedID) {
		m.selectedID = ""
	}
}

func (m *pickerModel) moveSelection(delta int) {
	if len(m.visible) == 0 {
		m.selectedID = ""
		return
	}
	index := 0
	for i, item := range m.visible {
		if item.ID == m.selectedID {
			index = i
			break
		}
	}
	index += delta
	if index < 0 {
		index = 0
	}
	if index >= len(m.visible) {
		index = len(m.visible) - 1
	}
	m.selectedID = m.visible[index].ID
}

func (m *pickerModel) cycleView(delta int) {
	order := []string{pickerViewSpaces, pickerViewAgents, pickerViewAll}
	index := 0
	for i, view := range order {
		if view == m.view {
			index = i
			break
		}
	}
	index = (index + delta) % len(order)
	if index < 0 {
		index += len(order)
	}
	m.view = order[index]
	m.allItems = BuildPickerItems(m.view, m.snapshot, m.history, m.spaceRows, m.agentRows)
	m.visible = FilterPickerItems(m.allItems, m.query)
	if m.selectedID == "" || !pickerItemByID(m.visible, m.selectedID) {
		m.selectedID = PreselectPickerItemID(m.view, m.visible, m.history, m.launch)
	}
}

type pickerAcceptedMsg struct{}

func (m pickerModel) acceptCmd() tea.Cmd {
	item, ok := m.selectedItem()
	if !ok {
		return nil
	}
	return func() tea.Msg {
		var err error
		if item.Kind == pickerKindAgent {
			err = FocusHerdrAgent(item.PaneID)
		} else {
			err = FocusHerdrWorkspace(item.WorkspaceID)
		}
		if err != nil {
			return previewLoadedMsg{targetID: item.ID, err: err}
		}
		return pickerAcceptedMsg{}
	}
}

func (m pickerModel) View() string {
	if m.width == 0 {
		return "hseh"
	}
	header := "hseh  " + m.view + "  /" + m.query
	listWidth := m.width
	showPreview := m.wideEnoughForPreview()
	if showPreview {
		listWidth = m.width / 2
	}
	listBody := m.renderList(listWidth, m.height-2)
	if !showPreview {
		return lipgloss.JoinVertical(lipgloss.Left, header, listBody)
	}
	preview := m.renderPreview(m.width-listWidth, m.height-2)
	return lipgloss.JoinVertical(lipgloss.Left, header, lipgloss.JoinHorizontal(lipgloss.Top, listBody, preview))
}

func (m pickerModel) renderList(width, height int) string {
	if height < 1 {
		height = 1
	}
	var lines []string
	if len(m.visible) == 0 {
		lines = []string{"(no results)"}
	}
	for _, item := range m.visible {
		prefix := "  "
		if item.ID == m.selectedID {
			prefix = "> "
		}
		block := strings.Join(item.Rows, "\n")
		if block == "" {
			block = item.ID
		}
		for i, line := range strings.Split(block, "\n") {
			if i == 0 {
				lines = append(lines, wrapLine(prefix+line, width)...)
			} else {
				lines = append(lines, wrapLine("  "+line, width)...)
			}
		}
		lines = append(lines, "")
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return lipgloss.NewStyle().Width(width).Height(height).Render(strings.Join(lines, "\n"))
}

func (m pickerModel) renderPreview(width, height int) string {
	text := m.previewText
	if m.previewErr != "" {
		text = m.previewErr
	}
	if text == "" {
		text = "(preview)"
	}
	return lipgloss.NewStyle().Width(width).Height(height).Render(text)
}

func wrapLine(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	var lines []string
	runes := []rune(line)
	for len(runes) > width {
		lines = append(lines, string(runes[:width]))
		runes = runes[width:]
	}
	lines = append(lines, string(runes))
	return lines
}

func runPicker(view string) error {
	snapshot, err := LoadHerdrSessionSnapshot()
	if err != nil {
		return err
	}
	witness, err := ReadServerContinuityWitness()
	if err != nil {
		return err
	}
	stateDir := pluginStateDir()
	var history FocusHistory
	if err := withFocusHistoryLock(stateDir, func() error {
		loaded, loadErr := LoadValidatedFocusHistory(stateDir, witness)
		if loadErr != nil {
			return loadErr
		}
		history = pruneFocusHistory(loaded, snapshot)
		return writeFocusHistoryFile(stateDir, history)
	}); err != nil {
		return err
	}
	spaceRows, agentRows := LoadSidebarTokenRows("")
	model := newPickerModel(view, snapshot, history, spaceRows, agentRows, LoadPreviewPollInterval())
	_, err = tea.NewProgram(model, tea.WithAltScreen()).Run()
	return err
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"syscall"
)

const workspaceSwitchCycleTimeoutMs = 500

// AgentLiveID is pane id plus occupant generation, not a conversation id.
type AgentLiveID struct {
	PaneID     string `json:"pane_id"`
	Generation int    `json:"generation"`
}

func (id AgentLiveID) String() string {
	return fmt.Sprintf("%s#%d", id.PaneID, id.Generation)
}

// PaneOccupant is the verified agent occupant of one pane.
type PaneOccupant struct {
	Generation   int    `json:"generation"`
	AgentKind    string `json:"agent_kind"`
	SessionValue string `json:"session_value,omitempty"`
}

// WorkspaceSwitchCycle is the in-progress 500ms previous-space cycle.
type WorkspaceSwitchCycle struct {
	Order        []string `json:"order"`
	Target       string   `json:"target"`
	LastSwitchAt int64    `json:"last_switch_at"`
}

// FocusHistory is session-scoped space and agent recency for one proven server.
type FocusHistory struct {
	Witness   ServerContinuityWitness `json:"witness"`
	Spaces    []string                `json:"spaces"`
	Agents    []AgentLiveID           `json:"agents,omitempty"`
	Occupants map[string]PaneOccupant `json:"occupants"`
	Cycle     *WorkspaceSwitchCycle   `json:"cycle,omitempty"`
	Pending   []string                `json:"pending,omitempty"`
}

func emptyFocusHistory(witness ServerContinuityWitness) FocusHistory {
	return FocusHistory{
		Witness:   witness,
		Occupants: map[string]PaneOccupant{},
	}
}

func historyStatePath(stateDir string) string {
	return filepath.Join(stateDir, "history.json")
}

func historyLockPath(stateDir string) string {
	return filepath.Join(stateDir, "history.lock")
}

func loadFocusHistoryFile(stateDir string) (FocusHistory, error) {
	payload, err := os.ReadFile(historyStatePath(stateDir))
	if err != nil {
		if os.IsNotExist(err) {
			return FocusHistory{Occupants: map[string]PaneOccupant{}}, nil
		}
		return FocusHistory{}, fmt.Errorf("hseh history: read: %w", err)
	}
	var history FocusHistory
	if err := json.Unmarshal(payload, &history); err != nil {
		return FocusHistory{}, fmt.Errorf("hseh history: parse: %w", err)
	}
	if history.Occupants == nil {
		history.Occupants = map[string]PaneOccupant{}
	}
	return history, nil
}

func writeFocusHistoryFile(stateDir string, history FocusHistory) error {
	if err := os.MkdirAll(stateDir, 0o700); err != nil {
		return fmt.Errorf("hseh history: mkdir: %w", err)
	}
	payload, err := json.Marshal(history)
	if err != nil {
		return fmt.Errorf("hseh history: encode: %w", err)
	}
	temporaryPath := filepath.Join(stateDir, fmt.Sprintf("history.%d.tmp", os.Getpid()))
	if err := os.WriteFile(temporaryPath, append(payload, '\n'), 0o600); err != nil {
		return fmt.Errorf("hseh history: write: %w", err)
	}
	if err := os.Rename(temporaryPath, historyStatePath(stateDir)); err != nil {
		return fmt.Errorf("hseh history: rename: %w", err)
	}
	return nil
}

func withFocusHistoryLock(stateDir string, fn func() error) error {
	if err := os.MkdirAll(stateDir, 0o700); err != nil {
		return fmt.Errorf("hseh history: mkdir: %w", err)
	}
	file, err := os.OpenFile(historyLockPath(stateDir), os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return fmt.Errorf("hseh history: lock: %w", err)
	}
	defer file.Close()
	if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX); err != nil {
		return fmt.Errorf("hseh history: flock: %w", err)
	}
	return fn()
}

// LoadValidatedFocusHistory loads history or drops it when the server process changed.
func LoadValidatedFocusHistory(stateDir string, live ServerContinuityWitness) (FocusHistory, error) {
	stored, err := loadFocusHistoryFile(stateDir)
	if err != nil {
		return emptyFocusHistory(live), err
	}
	if !sameServerContinuityWitness(stored.Witness, live) {
		return emptyFocusHistory(live), nil
	}
	stored.Witness = live
	return stored, nil
}

func pruneFocusHistory(history FocusHistory, snapshot HerdrSessionSnapshot) FocusHistory {
	liveSpaces := map[string]bool{}
	var spaceOrder []string
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID == "" {
			continue
		}
		liveSpaces[workspace.WorkspaceID] = true
		spaceOrder = append(spaceOrder, workspace.WorkspaceID)
	}
	history.Spaces = filterStrings(history.Spaces, liveSpaces)
	for _, id := range spaceOrder {
		if !containsString(history.Spaces, id) {
			history.Spaces = append(history.Spaces, id)
		}
	}
	history.Pending = filterStrings(history.Pending, liveSpaces)

	livePanes := map[string]HerdrAgentRow{}
	for _, agent := range snapshot.Agents {
		livePanes[agent.PaneID] = agent
	}
	occupants := map[string]PaneOccupant{}
	for paneID, occupant := range history.Occupants {
		agent, ok := livePanes[paneID]
		if !ok {
			continue
		}
		if occupantMatchesAgent(occupant, agent) {
			occupants[paneID] = occupant
		}
	}
	for paneID, agent := range livePanes {
		if _, ok := occupants[paneID]; ok {
			continue
		}
		occupants[paneID] = PaneOccupant{Generation: 1, AgentKind: agent.Agent, SessionValue: sessionValue(agent.AgentSession)}
	}
	history.Occupants = occupants

	var agents []AgentLiveID
	seen := map[string]bool{}
	for _, id := range history.Agents {
		occupant, ok := history.Occupants[id.PaneID]
		if !ok || occupant.Generation != id.Generation {
			continue
		}
		key := id.String()
		if seen[key] {
			continue
		}
		seen[key] = true
		agents = append(agents, id)
	}
	history.Agents = agents
	return history
}

func occupantMatchesAgent(occupant PaneOccupant, agent HerdrAgentRow) bool {
	if occupant.AgentKind != agent.Agent {
		return false
	}
	liveSession := sessionValue(agent.AgentSession)
	if occupant.SessionValue == "" && liveSession == "" {
		return true
	}
	return occupant.SessionValue != "" && occupant.SessionValue == liveSession
}

func sessionValue(session *HerdrAgentSession) string {
	if session == nil {
		return ""
	}
	return session.Value
}

func currentAgentLiveID(history FocusHistory, paneID string) (AgentLiveID, bool) {
	occupant, ok := history.Occupants[paneID]
	if !ok {
		return AgentLiveID{}, false
	}
	return AgentLiveID{PaneID: paneID, Generation: occupant.Generation}, true
}

// RecordWorkspaceFocus records a space as most recently used unless plugin-pending.
func RecordWorkspaceFocus(history FocusHistory, workspaceID string) FocusHistory {
	for index, id := range history.Pending {
		if id == workspaceID {
			history.Pending = append(history.Pending[:index], history.Pending[index+1:]...)
			return history
		}
	}
	history.Spaces = prependUnique(history.Spaces, workspaceID)
	history.Cycle = nil
	return history
}

// RemoveWorkspace drops a closed space from history.
func RemoveWorkspace(history FocusHistory, workspaceID string) FocusHistory {
	history.Spaces = removeString(history.Spaces, workspaceID)
	history.Pending = removeString(history.Pending, workspaceID)
	if history.Cycle != nil {
		history.Cycle.Order = removeString(history.Cycle.Order, workspaceID)
		if history.Cycle.Target == workspaceID || len(history.Cycle.Order) == 0 {
			history.Cycle = nil
		}
	}
	return history
}

// RecordAgentPaneFocus records the current occupant of a focused agent pane.
func RecordAgentPaneFocus(history FocusHistory, paneID string) FocusHistory {
	id, ok := currentAgentLiveID(history, paneID)
	if !ok {
		return history
	}
	history.Agents = prependAgentID(history.Agents, id)
	return history
}

// RekeyMovedPaneOccupant keeps the same occupant under the new pane id.
func RekeyMovedPaneOccupant(history FocusHistory, previousPaneID, paneID string) FocusHistory {
	occupant, ok := history.Occupants[previousPaneID]
	if !ok {
		return history
	}
	delete(history.Occupants, previousPaneID)
	history.Occupants[paneID] = occupant
	for index := range history.Agents {
		if history.Agents[index].PaneID == previousPaneID {
			history.Agents[index].PaneID = paneID
		}
	}
	return history
}

// ClearPaneOccupant drops a pane that no longer hosts that occupant.
func ClearPaneOccupant(history FocusHistory, paneID string) FocusHistory {
	delete(history.Occupants, paneID)
	var agents []AgentLiveID
	for _, id := range history.Agents {
		if id.PaneID != paneID {
			agents = append(agents, id)
		}
	}
	history.Agents = agents
	return history
}

// ApplyVerifiedOccupantTransition advances generation only when the occupant changed.
func ApplyVerifiedOccupantTransition(history FocusHistory, paneID, agentKind, sessionVal string, released bool) FocusHistory {
	if released || agentKind == "" {
		return ClearPaneOccupant(history, paneID)
	}
	existing, ok := history.Occupants[paneID]
	if !ok {
		history.Occupants[paneID] = PaneOccupant{Generation: 1, AgentKind: agentKind, SessionValue: sessionVal}
		return history
	}
	sameKind := existing.AgentKind == agentKind
	sameSession := existing.SessionValue == sessionVal || (existing.SessionValue == "" && sessionVal == "")
	if sameKind && sameSession {
		return history
	}
	next := existing.Generation + 1
	if next < 1 {
		next = 1
	}
	history.Occupants[paneID] = PaneOccupant{Generation: next, AgentKind: agentKind, SessionValue: sessionVal}
	var agents []AgentLiveID
	for _, id := range history.Agents {
		if !(id.PaneID == paneID && id.Generation == existing.Generation) {
			agents = append(agents, id)
		}
	}
	history.Agents = agents
	return history
}

// SelectNextWorkspace chooses the previous space, then cycles in sidebar order.
func SelectNextWorkspace(history FocusHistory, snapshot HerdrSessionSnapshot, nowMs int64) (FocusHistory, string) {
	var workspaceOrder []string
	current := snapshot.FocusedWorkspaceID
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID == "" {
			continue
		}
		if !containsString(workspaceOrder, workspace.WorkspaceID) {
			workspaceOrder = append(workspaceOrder, workspace.WorkspaceID)
		}
		if workspace.Focused && current == "" {
			current = workspace.WorkspaceID
		}
	}
	history = pruneFocusHistory(history, snapshot)
	if current == "" || len(workspaceOrder) < 2 {
		return history, ""
	}
	continuing := history.Cycle != nil && history.Cycle.Target == current && nowMs-history.Cycle.LastSwitchAt < workspaceSwitchCycleTimeoutMs
	if !continuing {
		history.Spaces = prependUnique(history.Spaces, current)
		history.Cycle = nil
	}
	var order []string
	if continuing {
		for _, id := range history.Cycle.Order {
			if containsString(workspaceOrder, id) {
				order = append(order, id)
			}
		}
		for _, id := range workspaceOrder {
			if !containsString(order, id) {
				order = append(order, id)
			}
		}
	} else {
		order = append(order, workspaceOrder...)
	}
	var target string
	if continuing {
		index := -1
		for i, id := range order {
			if id == current {
				index = i
				break
			}
		}
		target = order[(index+1)%len(order)]
	} else {
		for _, id := range history.Spaces {
			if id != current {
				target = id
				break
			}
		}
	}
	history.Cycle = &WorkspaceSwitchCycle{Order: order, Target: target, LastSwitchAt: nowMs}
	history.Pending = append(history.Pending, target)
	return history, target
}

func prependUnique(ids []string, id string) []string {
	out := []string{id}
	for _, existing := range ids {
		if existing != id {
			out = append(out, existing)
		}
	}
	return out
}

func prependAgentID(ids []AgentLiveID, id AgentLiveID) []AgentLiveID {
	out := []AgentLiveID{id}
	for _, existing := range ids {
		if existing.String() != id.String() {
			out = append(out, existing)
		}
	}
	return out
}

func containsString(ids []string, target string) bool {
	for _, id := range ids {
		if id == target {
			return true
		}
	}
	return false
}

func removeString(ids []string, target string) []string {
	var out []string
	for _, id := range ids {
		if id != target {
			out = append(out, id)
		}
	}
	return out
}

func filterStrings(ids []string, allowed map[string]bool) []string {
	var out []string
	for _, id := range ids {
		if allowed[id] {
			out = append(out, id)
		}
	}
	return out
}

func agentPriorityRank(status string) int {
	switch status {
	case "blocked":
		return 0
	case "done":
		return 1
	case "working":
		return 2
	case "idle":
		return 3
	default:
		return 4
	}
}

