type herdrSnapshotEnvelope struct {
	Type     string                `json:"type"`
	Snapshot *HerdrSessionSnapshot `json:"snapshot"`
}

// LoadHerdrSessionSnapshot loads the current session snapshot over the socket.
func LoadHerdrSessionSnapshot() (HerdrSessionSnapshot, error) {
	var raw json.RawMessage
	if err := CallHerdrMethod("session.snapshot", map[string]any{}, &raw); err != nil {
		return HerdrSessionSnapshot{}, err
	}
	var envelope herdrSnapshotEnvelope
	if err := json.Unmarshal(raw, &envelope); err != nil {
		return HerdrSessionSnapshot{}, fmt.Errorf("hseh herdr socket: session.snapshot: %w", err)
	}
	if envelope.Snapshot != nil {
		return *envelope.Snapshot, nil
	}
	var snapshot HerdrSessionSnapshot
	if err := json.Unmarshal(raw, &snapshot); err != nil {
		return HerdrSessionSnapshot{}, fmt.Errorf("hseh herdr socket: session.snapshot: %w", err)
	}
	if snapshot.Version == "" && len(snapshot.Workspaces) == 0 {
		return HerdrSessionSnapshot{}, fmt.Errorf("hseh herdr socket: session.snapshot missing snapshot")
	}
	return snapshot, nil
}

// FocusHerdrWorkspace focuses a live workspace.
func FocusHerdrWorkspace(workspaceID string) error {
	var result json.RawMessage
	return CallHerdrMethod("workspace.focus", map[string]any{"workspace_id": workspaceID}, &result)
}

// FocusHerdrAgent focuses the agent in a pane. Pane ids are valid agent targets.
func FocusHerdrAgent(paneID string) error {
	var result json.RawMessage
	return CallHerdrMethod("agent.focus", map[string]any{"target": paneID}, &result)
}

