}

type herdrPaneReadEnvelope struct {
	Type   string               `json:"type"`
	Read   *HerdrPaneReadResult `json:"read"`
	Result *HerdrPaneReadResult `json:"result"`
	HerdrPaneReadResult
}

// ReadHerdrPaneVisibleANSI reads the visible viewport without focusing the pane.
func ReadHerdrPaneVisibleANSI(paneID string) (HerdrPaneReadResult, error) {
	var envelope herdrPaneReadEnvelope
	params := map[string]any{
		"pane_id":    paneID,
		"source":     "visible",
		"format":     "ansi",
		"strip_ansi": false,
	}
	if err := CallHerdrMethod("pane.read", params, &envelope); err != nil {
		return HerdrPaneReadResult{}, err
	}
	if envelope.Read != nil {
		return *envelope.Read, nil
	}
	if envelope.Result != nil {
		return *envelope.Result, nil
	}
	if envelope.PaneID != "" || envelope.Text != "" {
		return envelope.HerdrPaneReadResult, nil
	}
	return HerdrPaneReadResult{}, fmt.Errorf("hseh herdr socket: pane.read missing text for %s", paneID)
}

// ActiveWorkspacePaneID returns the active pane in a workspace's active tab.
func ActiveWorkspacePaneID(snapshot HerdrSessionSnapshot, workspaceID string) string {
	activeTabID := ""
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID == workspaceID {
			activeTabID = workspace.ActiveTabID
			break
		}
	}
	if activeTabID == "" {
		return ""
	}
	for _, layout := range snapshot.Layouts {
		if layout.TabID == activeTabID {
			return layout.FocusedPaneID
		}
	}
	return ""
}

func workspaceByID(snapshot HerdrSessionSnapshot, workspaceID string) (HerdrWorkspaceRow, bool) {
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID == workspaceID {
			return workspace, true
		}
	}
	return HerdrWorkspaceRow{}, false
}

func tabByID(snapshot HerdrSessionSnapshot, tabID string) (HerdrTabRow, bool) {
	for _, tab := range snapshot.Tabs {
		if tab.TabID == tabID {
			return tab, true
		}
	}
	return HerdrTabRow{}, false
}

func paneByID(snapshot HerdrSessionSnapshot, paneID string) (HerdrPaneRow, bool) {
	for _, pane := range snapshot.Panes {
		if pane.PaneID == paneID {
			return pane, true
		}
	}
	return HerdrPaneRow{}, false
}

