import (
	"fmt"
	"net"
	"os"
	"strconv"
	"strings"
	"syscall"
)

// ServerContinuityWitness proves the Herdr server process is the same one that
// wrote history. Matching labels or socket paths are not continuity.
type ServerContinuityWitness struct {
	SocketPath    string `json:"socket_path"`
	PeerPID       int    `json:"peer_pid"`
	PeerStartTime string `json:"peer_start_time"`
}

// ReadServerContinuityWitness reads Linux SO_PEERCRED plus /proc start time.
func ReadServerContinuityWitness() (ServerContinuityWitness, error) {
	socketPath := HerdrSocketPath()
	if socketPath == "" {
		return ServerContinuityWitness{}, fmt.Errorf("hseh history: HERDR_SOCKET_PATH is not set")
	}
	conn, err := net.Dial("unix", socketPath)
	if err != nil {
		return ServerContinuityWitness{}, fmt.Errorf("hseh history: dial for continuity witness: %w", err)
	}
	defer conn.Close()
	unixConn, ok := conn.(*net.UnixConn)
	if !ok {
		return ServerContinuityWitness{}, fmt.Errorf("hseh history: continuity witness requires a unix socket")
	}
	raw, err := unixConn.SyscallConn()
	if err != nil {
		return ServerContinuityWitness{}, fmt.Errorf("hseh history: continuity witness control: %w", err)
	}
	var cred *syscall.Ucred
	var credErr error
	if err := raw.Control(func(fd uintptr) {
		cred, credErr = syscall.GetsockoptUcred(int(fd), syscall.SOL_SOCKET, syscall.SO_PEERCRED)
	}); err != nil {
		return ServerContinuityWitness{}, fmt.Errorf("hseh history: continuity witness control: %w", err)
	}
	if credErr != nil {
		return ServerContinuityWitness{}, fmt.Errorf("hseh history: continuity witness peer cred: %w", credErr)
	}
	if cred == nil || cred.Pid <= 0 {
		return ServerContinuityWitness{}, fmt.Errorf("hseh history: continuity witness missing peer pid")
	}
	startTime, err := readProcStartTime(int(cred.Pid))
	if err != nil {
		return ServerContinuityWitness{}, err
	}
	return ServerContinuityWitness{
		SocketPath:    socketPath,
		PeerPID:       int(cred.Pid),
		PeerStartTime: startTime,
	}, nil
}

func readProcStartTime(pid int) (string, error) {
	payload, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
	if err != nil {
		return "", fmt.Errorf("hseh history: continuity witness /proc/%d/stat: %w", pid, err)
	}
	text := string(payload)
	closeParen := strings.LastIndex(text, ")")
	if closeParen < 0 || closeParen+2 >= len(text) {
		return "", fmt.Errorf("hseh history: continuity witness /proc/%d/stat missing comm", pid)
	}
	fields := strings.Fields(text[closeParen+2:])
	// /proc/pid/stat field 22 is starttime; fields after comm start at field 3.
	if len(fields) < 20 {
		return "", fmt.Errorf("hseh history: continuity witness /proc/%d/stat too short", pid)
	}
	return fields[19], nil
}

func sameServerContinuityWitness(stored, live ServerContinuityWitness) bool {
	return stored.SocketPath != "" &&
		stored.SocketPath == live.SocketPath &&
		stored.PeerPID != 0 &&
		stored.PeerPID == live.PeerPID &&
		stored.PeerStartTime != "" &&
		stored.PeerStartTime == live.PeerStartTime
}

