type pluginEventPayload struct {
	Type           string `json:"type"`
	Event          string `json:"event"`
	WorkspaceID    string `json:"workspace_id"`
	PaneID         string `json:"pane_id"`
	PreviousPaneID string `json:"previous_pane_id"`
	Agent          string `json:"agent"`
	Released       bool   `json:"released"`
}

func runPluginEvent() error {
	name := os.Getenv("HERDR_PLUGIN_EVENT")
	if name == "" {
		return fmt.Errorf("hseh event: HERDR_PLUGIN_EVENT is not set")
	}
	var payload pluginEventPayload
	if raw := os.Getenv("HERDR_PLUGIN_EVENT_JSON"); raw != "" {
		_ = json.Unmarshal([]byte(raw), &payload)
	}
	workspaceID := firstNonEmpty(payload.WorkspaceID, os.Getenv("HERDR_WORKSPACE_ID"))
	paneID := firstNonEmpty(payload.PaneID, os.Getenv("HERDR_PANE_ID"))
	stateDir := pluginStateDir()
	witness, err := ReadServerContinuityWitness()
	if err != nil {
		return err
	}
	return withFocusHistoryLock(stateDir, func() error {
		history, err := LoadValidatedFocusHistory(stateDir, witness)
		if err != nil {
			return err
		}
		switch name {
		case "workspace.focused":
			if workspaceID != "" {
				history = RecordWorkspaceFocus(history, workspaceID)
			}
		case "workspace.closed":
			if workspaceID != "" {
				history = RemoveWorkspace(history, workspaceID)
			}
		case "pane.focused":
			if paneID != "" {
				history = ensurePaneOccupantFromLive(history, paneID)
				history = RecordAgentPaneFocus(history, paneID)
			}
		case "pane.closed", "pane.exited":
			if paneID != "" {
				history = ClearPaneOccupant(history, paneID)
			}
		case "pane.moved":
			previous := payload.PreviousPaneID
			if previous != "" && paneID != "" {
				history = RekeyMovedPaneOccupant(history, previous, paneID)
			}
		case "pane.agent_detected":
			if paneID != "" {
				history = ApplyVerifiedOccupantTransition(history, paneID, payload.Agent, "", payload.Released)
			}
		default:
			return nil
		}
		return writeFocusHistoryFile(stateDir, history)
	})
}

func ensurePaneOccupantFromLive(history FocusHistory, paneID string) FocusHistory {
	if _, ok := history.Occupants[paneID]; ok {
		return history
	}
	snapshot, err := LoadHerdrSessionSnapshot()
	if err != nil {
		return history
	}
	for _, agent := range snapshot.Agents {
		if agent.PaneID == paneID {
			history.Occupants[paneID] = PaneOccupant{
				Generation:   1,
				AgentKind:    agent.Agent,
				SessionValue: sessionValue(agent.AgentSession),
			}
			return history
		}
	}
	return history
}

func runWorkspaceSwitch() error {
	snapshot, err := LoadHerdrSessionSnapshot()
	if err != nil {
		return err
	}
	witness, err := ReadServerContinuityWitness()
	if err != nil {
		return err
	}
	stateDir := pluginStateDir()
	var target string
	if err := withFocusHistoryLock(stateDir, func() error {
		history, loadErr := LoadValidatedFocusHistory(stateDir, witness)
		if loadErr != nil {
			return loadErr
		}
		history, target = SelectNextWorkspace(history, snapshot, time.Now().UnixMilli())
		if writeErr := writeFocusHistoryFile(stateDir, history); writeErr != nil {
			return writeErr
		}
		return nil
	}); err != nil {
		return err
	}
	if target == "" {
		return nil
	}
	return FocusHerdrWorkspace(target)
}

func runPickerList(view string) error {
	if view == "" {
		view = pickerViewSpaces
	}
	snapshot, err := LoadHerdrSessionSnapshot()
	if err != nil {
		return err
	}
	witness, err := ReadServerContinuityWitness()
	if err != nil {
		return err
	}
	stateDir := pluginStateDir()
	var history FocusHistory
	if err := withFocusHistoryLock(stateDir, func() error {
		loaded, loadErr := LoadValidatedFocusHistory(stateDir, witness)
		if loadErr != nil {
			return loadErr
		}
		history = pruneFocusHistory(loaded, snapshot)
		return writeFocusHistoryFile(stateDir, history)
	}); err != nil {
		return err
	}
	spaceRows, agentRows := LoadSidebarTokenRows("")
	items := BuildPickerItems(view, snapshot, history, spaceRows, agentRows)
	doc := PickerListDocument{
		Session: PickerListSession{Name: herdrSessionName(HerdrSocketPath()), SocketPath: HerdrSocketPath()},
		View:    view,
		Items:   items,
	}
	payload, err := encodePickerListJSON(doc)
	if err != nil {
		return err
	}
	fmt.Println(string(payload))
	return nil
}

package main

import (
	"encoding/json"
	"os"
	"sort"
	"strings"

	"github.com/sahilm/fuzzy"
)

const (
	pickerKindSpace  = "space"
	pickerKindAgent  = "agent"
	pickerViewSpaces = "spaces"
	pickerViewAgents = "agents"
	pickerViewAll    = "all"
)

// PickerItem is one flat picker row with a stable target id.
type PickerItem struct {
	Kind        string   `json:"kind"`
	ID          string   `json:"id"`
	WorkspaceID string   `json:"workspace_id,omitempty"`
	PaneID      string   `json:"pane_id,omitempty"`
	Label       string   `json:"label,omitempty"`
	Status      string   `json:"status,omitempty"`
	Rows        []string `json:"rows"`
	SearchText  string   `json:"-"`
	PreviewPane string   `json:"-"`
}

// PickerListDocument is the public JSON listing shape.
type PickerListDocument struct {
	Session PickerListSession `json:"session"`
	View    string            `json:"view"`
	Items   []PickerItem      `json:"items"`
	Errors  []string          `json:"errors,omitempty"`
}

// PickerListSession names the Herdr session the listing came from.
type PickerListSession struct {
	Name       string `json:"name"`
	SocketPath string `json:"socket_path"`
}

func herdrSessionName(socketPath string) string {
	if name := os.Getenv("HERDR_SESSION"); name != "" {
		return name
	}
	const marker = "/sessions/"
	if index := strings.Index(socketPath, marker); index >= 0 {
		rest := socketPath[index+len(marker):]
		if slash := strings.Index(rest, "/"); slash > 0 {
			return rest[:slash]
		}
	}
	return "default"
}

// BuildPickerItems builds Spaces, Agents, or All rows from live snapshot plus history.
func BuildPickerItems(view string, snapshot HerdrSessionSnapshot, history FocusHistory, spaceRows, agentRows [][]string) []PickerItem {
	spaces := buildSpacePickerItems(snapshot, history, spaceRows)
	agents := buildAgentPickerItems(snapshot, history, agentRows)
	switch view {
	case pickerViewAgents:
		return agents
	case pickerViewAll:
		return append(append([]PickerItem{}, spaces...), agents...)
	default:
		return spaces
	}
}

func buildSpacePickerItems(snapshot HerdrSessionSnapshot, history FocusHistory, spaceRows [][]string) []PickerItem {
	indexOf := map[string]int{}
	for i, id := range history.Spaces {
		indexOf[id] = i
	}
	workspaces := append([]HerdrWorkspaceRow{}, snapshot.Workspaces...)
	sort.SliceStable(workspaces, func(i, j int) bool {
		left, leftOK := indexOf[workspaces[i].WorkspaceID]
		right, rightOK := indexOf[workspaces[j].WorkspaceID]
		if leftOK && rightOK {
			return left < right
		}
		if leftOK {
			return true
		}
		if rightOK {
			return false
		}
		return i < j
	})
	var items []PickerItem
	for _, workspace := range workspaces {
		rows := renderSpaceSidebarRows(workspace, spaceRows)
		items = append(items, PickerItem{
			Kind:        pickerKindSpace,
			ID:          workspace.WorkspaceID,
			WorkspaceID: workspace.WorkspaceID,
			Label:       workspace.Label,
			Status:      workspace.AgentStatus,
			Rows:        rows,
			SearchText:  strings.Join(rows, " "),
			PreviewPane: ActiveWorkspacePaneID(snapshot, workspace.WorkspaceID),
		})
	}
	return items
}

func buildAgentPickerItems(snapshot HerdrSessionSnapshot, history FocusHistory, agentRows [][]string) []PickerItem {
	agents := append([]HerdrAgentRow{}, snapshot.Agents...)
	sort.SliceStable(agents, func(i, j int) bool {
		left := agentPriorityRank(agents[i].AgentStatus)
		right := agentPriorityRank(agents[j].AgentStatus)
		if left != right {
			return left < right
		}
		if agents[i].StateChangeSeq != agents[j].StateChangeSeq {
			return agents[i].StateChangeSeq > agents[j].StateChangeSeq
		}
		return i < j
	})
	var items []PickerItem
	for _, agent := range agents {
		liveID, ok := currentAgentLiveID(history, agent.PaneID)
		if !ok {
			liveID = AgentLiveID{PaneID: agent.PaneID, Generation: 1}
		}
		rows := renderAgentSidebarRows(snapshot, agent, agentRows)
		items = append(items, PickerItem{
			Kind:        pickerKindAgent,
			ID:          liveID.String(),
			WorkspaceID: agent.WorkspaceID,
			PaneID:      agent.PaneID,
			Label:       firstNonEmpty(agent.DisplayAgent, agent.Title, agent.Agent, agent.PaneID),
			Status:      agent.AgentStatus,
			Rows:        rows,
			SearchText:  strings.Join(rows, " "),
			PreviewPane: agent.PaneID,
		})
	}
	return items
}

func renderSpaceSidebarRows(workspace HerdrWorkspaceRow, layout [][]string) []string {
	values := map[string]string{
		"state_text": workspace.AgentStatus,
		"workspace":  workspace.Label,
	}
	if workspace.AgentStatus != "" {
		values["state_icon"] = workspace.AgentStatus
	}
	for name, token := range workspace.Tokens {
		values["$"+name] = token
	}
	return renderTokenRows(layout, values)
}

func renderAgentSidebarRows(snapshot HerdrSessionSnapshot, agent HerdrAgentRow, layout [][]string) []string {
	workspaceLabel := agent.WorkspaceID
	if workspace, ok := workspaceByID(snapshot, agent.WorkspaceID); ok && workspace.Label != "" {
		workspaceLabel = workspace.Label
	}
	tabLabel := ""
	if tab, ok := tabByID(snapshot, agent.TabID); ok {
		tabLabel = tab.Label
	}
	paneLabel := agent.Label
	values := map[string]string{
		"state_text":              firstNonEmpty(agent.StateLabels[agent.AgentStatus], agent.AgentStatus),
		"workspace":               workspaceLabel,
		"tab":                     tabLabel,
		"pane":                    paneLabel,
		"agent":                   firstNonEmpty(agent.DisplayAgent, agent.Agent),
		"terminal_title":          agent.TerminalTitle,
		"terminal_title_stripped": agent.TitleStripped,
	}
	if agent.AgentStatus != "" {
		values["state_icon"] = agent.AgentStatus
	}
	for name, token := range agent.Tokens {
		values["$"+name] = token
	}
	return renderTokenRows(layout, values)
}

func renderTokenRows(layout [][]string, values map[string]string) []string {
	var rows []string
	for _, tokens := range layout {
		var parts []string
		for _, token := range tokens {
			value := strings.TrimSpace(values[token])
			if value == "" {
				continue
			}
			if token == "state_icon" {
				parts = append(parts, value)
				continue
			}
			parts = append(parts, value)
		}
		if len(parts) == 0 {
			continue
		}
		rows = append(rows, strings.Join(parts, " · "))
	}
	return rows
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

// FilterPickerItems ranks matching items by fuzzy quality, then original order.
func FilterPickerItems(items []PickerItem, query string) []PickerItem {
	query = strings.TrimSpace(query)
	if query == "" {
		return items
	}
	targets := make([]string, len(items))
	for i, item := range items {
		targets[i] = item.SearchText
	}
	matches := fuzzy.Find(query, targets)
	sort.SliceStable(matches, func(i, j int) bool {
		if matches[i].Score != matches[j].Score {
			return matches[i].Score > matches[j].Score
		}
		return matches[i].Index < matches[j].Index
	})
	var filtered []PickerItem
	for _, match := range matches {
		filtered = append(filtered, items[match.Index])
	}
	return filtered
}

func encodePickerListJSON(doc PickerListDocument) ([]byte, error) {
	if doc.Items == nil {
		doc.Items = []PickerItem{}
	}
	return json.MarshalIndent(doc, "", "  ")
}

package main

import (
	"os"
	"path/filepath"

	"github.com/BurntSushi/toml"
)

type sidebarFile struct {
	UI struct {
		Sidebar struct {
			Agents struct {
				Rows [][]any `toml:"rows"`
			} `toml:"agents"`
			Spaces struct {
				Rows [][]any `toml:"rows"`
			} `toml:"spaces"`
		} `toml:"sidebar"`
	} `toml:"ui"`
}

func defaultAgentSidebarRows() [][]string {
	return [][]string{{"state_icon", "machine", "workspace", "tab"}, {"agent"}}
}

func defaultSpaceSidebarRows() [][]string {
	return [][]string{{"state_icon", "workspace"}, {"branch", "git_status"}}
}

// LoadSidebarTokenRows reads ui.sidebar rows from Herdr config.toml.
func LoadSidebarTokenRows(configPath string) (spaceRows, agentRows [][]string) {
	spaceRows = defaultSpaceSidebarRows()
	agentRows = defaultAgentSidebarRows()
	if configPath == "" {
		configPath = herdrConfigPath()
	}
	payload, err := os.ReadFile(configPath)
	if err != nil {
		return spaceRows, agentRows
	}
	var file sidebarFile
	if err := toml.Unmarshal(payload, &file); err != nil {
		return spaceRows, agentRows
	}
	if parsed := parseSidebarRows(file.UI.Sidebar.Spaces.Rows); len(parsed) > 0 {
		spaceRows = parsed
	}
	if parsed := parseSidebarRows(file.UI.Sidebar.Agents.Rows); len(parsed) > 0 {
		agentRows = parsed
	}
	return spaceRows, agentRows
}

func herdrConfigPath() string {
	if path := os.Getenv("HERDR_CONFIG_PATH"); path != "" {
		return path
	}
	if dir := os.Getenv("XDG_CONFIG_HOME"); dir != "" {
		return filepath.Join(dir, "herdr", "config.toml")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config", "herdr", "config.toml")
}

func parseSidebarRows(raw [][]any) [][]string {
	var rows [][]string
	for _, row := range raw {
		var tokens []string
		for _, cell := range row {
			switch value := cell.(type) {
			case string:
				if value != "" {
					tokens = append(tokens, value)
				}
			case map[string]any:
				if token, ok := value["token"].(string); ok && token != "" {
					tokens = append(tokens, token)
				}
			}
		}
		if len(tokens) > 0 {
			rows = append(rows, tokens)
		}
	}
	return rows
}

package main

import (
	"strings"
	"unicode/utf8"
)

// AllowVisiblePreviewANSI keeps SGR color sequences and drops cursor, OSC,
// clipboard, and other terminal-control effects. This is not a terminal emulator.
func AllowVisiblePreviewANSI(input string) string {
	var out strings.Builder
	out.Grow(len(input))
	for i := 0; i < len(input); {
		r, size := utf8.DecodeRuneInString(input[i:])
		if r == 0x1b {
			consumed, keep := consumeEscape(input[i:])
			if keep != "" {
				out.WriteString(keep)
			}
			i += consumed
			continue
		}
		if r == 0x07 || r == 0x18 || r == 0x1a {
			i += size
			continue
		}
		if r < 0x20 && r != '\n' && r != '\t' && r != '\r' {
			i += size
			continue
		}
		out.WriteString(input[i : i+size])
		i += size
	}
	return out.String()
}

func consumeEscape(input string) (int, string) {
	if len(input) < 2 {
		return len(input), ""
	}
	switch input[1] {
	case '[':
		return consumeCSI(input)
	case ']':
		return consumeTerminated(input, true), ""
	case 'P', 'X', '^', '_':
		return consumeTerminated(input, false), ""
	default:
		if input[1] >= 0x40 && input[1] <= 0x5f {
			return 2, ""
		}
		return 2, ""
	}
}

func consumeCSI(input string) (int, string) {
	i := 2
	for i < len(input) {
		b := input[i]
		if b >= 0x40 && b <= 0x7e {
			i++
			if b == 'm' {
				return i, input[:i]
			}
			return i, ""
		}
		i++
	}
	return len(input), ""
}

func consumeTerminated(input string, osc bool) int {
	i := 2
	for i < len(input) {
		if input[i] == 0x07 {
			return i + 1
		}
		if input[i] == 0x1b && i+1 < len(input) && input[i+1] == '\\' {
			return i + 2
		}
		i++
	}
	_ = osc
	return len(input)
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"net"
	"os"
	"sync/atomic"
)

var herdrRequestSeq atomic.Uint64

// HerdrSocketPath is the current session socket. HERDR_SOCKET_PATH wins.
func HerdrSocketPath() string {
	if path := os.Getenv("HERDR_SOCKET_PATH"); path != "" {
		return path
	}
	return ""
}

// CallHerdrMethod sends one newline-delimited JSON request and decodes the result.
func CallHerdrMethod(method string, params any, result any) error {
	socketPath := HerdrSocketPath()
	if socketPath == "" {
		return fmt.Errorf("hseh herdr socket: HERDR_SOCKET_PATH is not set")
	}
	conn, err := net.Dial("unix", socketPath)
	if err != nil {
		return fmt.Errorf("hseh herdr socket: dial %s: %w", socketPath, err)
	}
	defer conn.Close()

	id := fmt.Sprintf("hseh-%d", herdrRequestSeq.Add(1))
	request := struct {
		ID     string `json:"id"`
		Method string `json:"method"`
		Params any    `json:"params"`
	}{ID: id, Method: method, Params: params}
	if params == nil {
		request.Params = map[string]any{}
	}
	payload, err := json.Marshal(request)
	if err != nil {
		return fmt.Errorf("hseh herdr socket: encode %s: %w", method, err)
	}
	if _, err := conn.Write(append(payload, '\n')); err != nil {
		return fmt.Errorf("hseh herdr socket: write %s: %w", method, err)
	}

	line, err := bufio.NewReader(conn).ReadBytes('\n')
	if err != nil {
		return fmt.Errorf("hseh herdr socket: read %s: %w", method, err)
	}
	var envelope struct {
		ID     string          `json:"id"`
		Result json.RawMessage `json:"result"`
		Error  *struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(line, &envelope); err != nil {
		return fmt.Errorf("hseh herdr socket: decode %s: %w", method, err)
	}
	if envelope.Error != nil {
		return fmt.Errorf("hseh herdr socket: %s: %s %s", method, envelope.Error.Code, envelope.Error.Message)
	}
	if result == nil {
		return nil
	}
	if len(envelope.Result) == 0 {
		return fmt.Errorf("hseh herdr socket: %s response did not contain a result", method)
	}
	if err := json.Unmarshal(envelope.Result, result); err != nil {
		return fmt.Errorf("hseh herdr socket: decode %s result: %w", method, err)
	}
	return nil
}

package main

import (
	"os"
	"strings"
)

type pickerLaunchContext struct {
	FromAgentPane bool
	CurrentSpace  string
	CurrentAgent  string
}

func pickerLaunchFromEnv(snapshot HerdrSessionSnapshot, history FocusHistory) pickerLaunchContext {
	ctx := pickerLaunchContext{
		CurrentSpace: snapshot.FocusedWorkspaceID,
	}
	if snapshot.FocusedPaneID != "" {
		if id, ok := currentAgentLiveID(history, snapshot.FocusedPaneID); ok {
			ctx.CurrentAgent = id.String()
		}
		for _, agent := range snapshot.Agents {
			if agent.PaneID == snapshot.FocusedPaneID {
				ctx.FromAgentPane = true
				break
			}
		}
	}
	if os.Getenv("HERDR_PLUGIN_CONTEXT_JSON") != "" {
		// focused_pane_agent in context is enough to treat launch as from an agent pane.
		if !ctx.FromAgentPane {
			ctx.FromAgentPane = containsAgentContextJSON(os.Getenv("HERDR_PLUGIN_CONTEXT_JSON"))
		}
	}
	return ctx
}

func containsAgentContextJSON(raw string) bool {
	if strings.Contains(raw, `"focused_pane_agent":null`) || strings.Contains(raw, `"focused_pane_agent":""`) {
		return false
	}
	return strings.Contains(raw, `"focused_pane_agent":"`)
}

// PreselectPickerItemID chooses the previous target, then first non-current, then current.
func PreselectPickerItemID(view string, items []PickerItem, history FocusHistory, launch pickerLaunchContext) string {
	if len(items) == 0 {
		return ""
	}
	wanted := previousTargetID(view, history, launch)
	if wanted != "" && pickerItemByID(items, wanted) {
		return wanted
	}
	for _, item := range items {
		if !isCurrentPickerItem(item, launch) {
			return item.ID
		}
	}
	return items[0].ID
}

func previousTargetID(view string, history FocusHistory, launch pickerLaunchContext) string {
	switch view {
	case pickerViewAgents:
		return previousAgentID(history, launch.CurrentAgent)
	case pickerViewAll:
		if launch.FromAgentPane {
			if id := previousAgentID(history, launch.CurrentAgent); id != "" {
				return id
			}
		}
		return previousSpaceID(history, launch.CurrentSpace)
	default:
		return previousSpaceID(history, launch.CurrentSpace)
	}
}

func previousSpaceID(history FocusHistory, current string) string {
	for _, id := range history.Spaces {
		if id != current {
			return id
		}
	}
	return ""
}

func previousAgentID(history FocusHistory, current string) string {
	for _, id := range history.Agents {
		if id.String() != current {
			return id.String()
		}
	}
	return ""
}

func isCurrentPickerItem(item PickerItem, launch pickerLaunchContext) bool {
	if item.Kind == pickerKindSpace {
		return item.ID == launch.CurrentSpace
	}
	return item.ID == launch.CurrentAgent
}

func pickerItemByID(items []PickerItem, id string) bool {
	for _, item := range items {
		if item.ID == id {
			return true
		}
	}
	return false
}

