	"github.com/BurntSushi/toml"
)

// DefaultPreviewPollMilliseconds is the selected visible preview poll interval.
const DefaultPreviewPollMilliseconds = 500

// WidePopupPreviewMinColumns hides preview below this inner width.
const WidePopupPreviewMinColumns = 80

func pluginStateDir() string {
	if dir := os.Getenv("HERDR_PLUGIN_STATE_DIR"); dir != "" {
		return dir
	}
	if dir := os.Getenv("XDG_STATE_HOME"); dir != "" {
		return filepath.Join(dir, "hseh")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".local", "state", "hseh")
}

func pluginConfigDir() string {
	if dir := os.Getenv("HERDR_PLUGIN_CONFIG_DIR"); dir != "" {
		return dir
	}
	if dir := os.Getenv("XDG_CONFIG_HOME"); dir != "" {
		return filepath.Join(dir, "hseh")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config", "hseh")
}

type hsehFileConfig struct {
	PreviewPollMs int `toml:"preview_poll_ms"`
}

// LoadPreviewPollInterval reads preview_poll_ms from plugin config, else 500ms.
func LoadPreviewPollInterval() time.Duration {
	path := filepath.Join(pluginConfigDir(), "hseh.toml")
	payload, err := os.ReadFile(path)
	if err != nil {
		return time.Duration(DefaultPreviewPollMilliseconds) * time.Millisecond
	}
	var file hsehFileConfig
	if err := toml.Unmarshal(payload, &file); err != nil || file.PreviewPollMs <= 0 {
		return time.Duration(DefaultPreviewPollMilliseconds) * time.Millisecond
	}
	return time.Duration(file.PreviewPollMs) * time.Millisecond
}

