package main

import (
	"fmt"
	"os"
)

func main() {
	if err := runHseh(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}
}

func runHseh(args []string) error {
	if len(args) == 0 {
		return runPicker(pickerViewSpaces)
	}
	switch args[0] {
	case "popup":
		view := pickerViewSpaces
		if len(args) > 1 {
			view = args[1]
		}
		return runPicker(view)
	case "list":
		view := pickerViewSpaces
		jsonOut := false
		for i := 1; i < len(args); i++ {
			switch args[i] {
			case "--json":
				jsonOut = true
			case "--view":
				if i+1 >= len(args) {
					return fmt.Errorf("hseh list: --view requires spaces, agents, or all")
				}
				i++
				view = args[i]
			default:
				if len(args[i]) > 7 && args[i][:7] == "--view=" {
					view = args[i][7:]
					continue
				}
				return fmt.Errorf("hseh list: unknown argument %s", args[i])
			}
		}
		if !jsonOut {
			return fmt.Errorf("hseh list: --json is required")
		}
		return runPickerList(view)
	case "switch":
		return runWorkspaceSwitch()
	case "event":
		return runPluginEvent()
	default:
		return fmt.Errorf("hseh: unknown command %s", args[0])
	}
}

package main

import (
	"fmt"
	"strings"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

type previewLoadedMsg struct {
	seq      uint64
	targetID string
	paneID   string
	text     string
	err      error
}

type snapshotTickMsg struct{}

type snapshotLoadedMsg struct {
	seq      uint64
	snapshot HerdrSessionSnapshot
	history  FocusHistory
	err      error
}

type pickerModel struct {
	view               string
	query              string
	allItems           []PickerItem
	visible            []PickerItem
	selectedID         string
	snapshot           HerdrSessionSnapshot
	history            FocusHistory
	spaceRows          [][]string
	agentRows          [][]string
	width              int
	height             int
	previewText        string
	previewErr         string
	statusErr          string
	pollEvery          time.Duration
	widePreviewMinCols int
	launch             pickerLaunchContext
	snapshotSeq        uint64
	previewSeq         uint64
	snapshotInFlight   bool
	previewInFlight    bool
	quitting           bool
}

func newPickerModel(view string, snapshot HerdrSessionSnapshot, history FocusHistory, spaceRows, agentRows [][]string, pollEvery time.Duration, wideMin int) pickerModel {
	history = pruneFocusHistory(history, snapshot)
	items := BuildPickerItems(view, snapshot, history, spaceRows, agentRows)
	launch := pickerLaunchFromEnv(snapshot, history)
	model := pickerModel{
		view:               view,
		allItems:           items,
		snapshot:           snapshot,
		history:            history,
		spaceRows:          spaceRows,
		agentRows:          agentRows,
		pollEvery:          pollEvery,
		widePreviewMinCols: wideMin,
		launch:             launch,
	}
	model.visible = FilterPickerItems(items, "")
	model.selectedID = PreselectPickerItemID(view, model.visible, history, launch)
	return model
}

func (m pickerModel) Init() tea.Cmd {
	return tea.Batch(m.previewCmd(), tickSnapshot(m.pollEvery))
}

func tickSnapshot(every time.Duration) tea.Cmd {
	return tea.Tick(every, func(time.Time) tea.Msg { return snapshotTickMsg{} })
}

func (m pickerModel) wideEnoughForPreview() bool {
	return m.width >= m.widePreviewMinCols
}

func (m pickerModel) selectedItem() (PickerItem, bool) {
	if m.selectedID == "" {
		return PickerItem{}, false
	}
	for _, item := range m.visible {
		if item.ID == m.selectedID {
			return item, true
		}
	}
	return PickerItem{}, false
}

func (m pickerModel) previewCmd() tea.Cmd {
	if m.quitting || m.previewInFlight || !m.wideEnoughForPreview() {
		return nil
	}
	item, ok := m.selectedItem()
	if !ok || item.PreviewPane == "" {
		return nil
	}
	m.previewInFlight = true
	m.previewSeq++
	seq := m.previewSeq
	targetID := item.ID
	paneID := item.PreviewPane
	return func() tea.Msg {
		result, _, err := ReadHerdrPaneVisibleANSI(paneID)
		if err != nil {
			return previewLoadedMsg{seq: seq, targetID: targetID, paneID: paneID, err: err}
		}
		return previewLoadedMsg{seq: seq, targetID: targetID, paneID: paneID, text: AllowVisiblePreviewANSI(result.Text)}
	}
}

func (m pickerModel) snapshotCmd() tea.Cmd {
	if m.quitting || m.snapshotInFlight {
		return nil
	}
	m.snapshotInFlight = true
	m.snapshotSeq++
	seq := m.snapshotSeq
	stateDir := pluginStateDir()
	return func() tea.Msg {
		snapshot, witness, err := LoadHerdrSessionSnapshot()
		if err != nil {
			return snapshotLoadedMsg{seq: seq, err: err}
		}
		var history FocusHistory
		lockErr := withFocusHistoryLock(stateDir, func() error {
			loaded, loadErr := LoadValidatedFocusHistory(stateDir, witness)
			if loadErr != nil {
				return loadErr
			}
			history = pruneFocusHistory(loaded, snapshot)
			return writeFocusHistoryFile(stateDir, history)
		})
		if lockErr != nil {
			return snapshotLoadedMsg{seq: seq, err: lockErr}
		}
		return snapshotLoadedMsg{seq: seq, snapshot: snapshot, history: history}
	}
}

func (m pickerModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		wasWide := m.wideEnoughForPreview()
		m.width = msg.Width
		m.height = msg.Height
		nowWide := m.wideEnoughForPreview()
		if !nowWide {
			m.previewText = ""
			m.previewSeq++
			if nowWide != wasWide {
				return m, nil
			}
			return m, nil
		}
		if nowWide && !wasWide {
			return m, m.previewCmd()
		}
		return m, nil
	case snapshotTickMsg:
		if m.quitting {
			return m, nil
		}
		cmds := []tea.Cmd{tickSnapshot(m.pollEvery)}
		if cmd := m.snapshotCmd(); cmd != nil {
			cmds = append(cmds, cmd)
		}
		if m.wideEnoughForPreview() {
			if cmd := m.previewCmd(); cmd != nil {
				cmds = append(cmds, cmd)
			}
		}
		return m, tea.Batch(cmds...)
	case snapshotLoadedMsg:
		m.snapshotInFlight = false
		if m.quitting || msg.seq != m.snapshotSeq {
			return m, nil
		}
		if msg.err != nil {
			m.statusErr = msg.err.Error()
			return m, nil
		}
		m.statusErr = ""
		m.snapshot = msg.snapshot
		m.history = msg.history
		m.rebuildItemsKeepOrder()
		return m, nil
	case previewLoadedMsg:
		m.previewInFlight = false
		if m.quitting || msg.seq != m.previewSeq {
			if !m.quitting && m.wideEnoughForPreview() {
				return m, m.previewCmd()
			}
			return m, nil
		}
		item, ok := m.selectedItem()
		if !ok || msg.targetID != m.selectedID || msg.paneID != item.PreviewPane {
			if m.wideEnoughForPreview() {
				return m, m.previewCmd()
			}
			return m, nil
		}
		if msg.err != nil {
			m.statusErr = msg.err.Error()
			m.previewErr = msg.err.Error()
			m.previewText = ""
			return m, nil
		}
		if !m.wideEnoughForPreview() {
			return m, nil
		}
		m.previewErr = ""
		m.previewText = msg.text
		return m, nil
	case pickerAcceptedMsg:
		return m, tea.Quit
	case pickerErrorMsg:
		m.statusErr = msg.err.Error()
		return m, nil
	case tea.KeyMsg:
		switch msg.Type {
		case tea.KeyCtrlC, tea.KeyEsc:
			m.quitting = true
			m.previewSeq++
			m.snapshotSeq++
			return m, tea.Quit
		case tea.KeyEnter:
			return m, m.acceptCmd()
		case tea.KeyUp:
			m.moveSelection(-1)
			return m, m.resetPreview()
		case tea.KeyDown:
			m.moveSelection(1)
			return m, m.resetPreview()
		case tea.KeyTab:
			m.cycleView(1)
			return m, m.resetPreview()
		case tea.KeyShiftTab:
			m.cycleView(-1)
			return m, m.resetPreview()
		case tea.KeyBackspace:
			if len(m.query) > 0 {
				r := []rune(m.query)
				m.query = string(r[:len(r)-1])
				m.applyQuery()
			}
			return m, m.resetPreview()
		default:
			if msg.Type == tea.KeyRunes {
				m.query += StripTerminalControls(string(msg.Runes))
				m.applyQuery()
				return m, m.resetPreview()
			}
		}
	}
	return m, nil
}

func (m *pickerModel) resetPreview() tea.Cmd {
	m.previewText = ""
	m.previewErr = ""
	m.previewSeq++
	return m.previewCmd()
}

func (m *pickerModel) applyQuery() {
	m.visible = FilterPickerItems(m.allItems, m.query)
	if pickerItemByID(m.visible, m.selectedID) {
		return
	}
	m.selectedID = ""
	if m.query == "" {
		m.selectedID = PreselectPickerItemID(m.view, m.visible, m.history, m.launch)
	}
}

func (m *pickerModel) rebuildItemsKeepOrder() {
	fresh := BuildPickerItems(m.view, m.snapshot, m.history, m.spaceRows, m.agentRows)
	byID := map[string]PickerItem{}
	for _, item := range fresh {
		byID[item.ID] = item
	}
	var kept []PickerItem
	seen := map[string]bool{}
	for _, item := range m.allItems {
		if next, ok := byID[item.ID]; ok {
			kept = append(kept, next)
			seen[item.ID] = true
		}
	}
	for _, item := range fresh {
		if !seen[item.ID] {
			kept = append(kept, item)
		}
	}
	m.allItems = kept
	if m.query == "" {
		m.visible = kept
	} else {
		var visible []PickerItem
		for _, item := range m.visible {
			if next, ok := byID[item.ID]; ok {
				visible = append(visible, next)
			}
		}
		m.visible = visible
	}
	if m.selectedID != "" && !pickerItemByID(m.visible, m.selectedID) {
		m.selectedID = ""
	}
}

func (m *pickerModel) moveSelection(delta int) {
	if len(m.visible) == 0 {
		m.selectedID = ""
		return
	}
	index := 0
	for i, item := range m.visible {
		if item.ID == m.selectedID {
			index = i
			break
		}
	}
	index += delta
	if index < 0 {
		index = 0
	}
	if index >= len(m.visible) {
		index = len(m.visible) - 1
	}
	m.selectedID = m.visible[index].ID
}

func (m *pickerModel) cycleView(delta int) {
	order := []string{pickerViewSpaces, pickerViewAgents, pickerViewAll}
	index := 0
	for i, view := range order {
		if view == m.view {
			index = i
			break
		}
	}
	index = (index + delta) % len(order)
	if index < 0 {
		index += len(order)
	}
	m.view = order[index]
	m.allItems = BuildPickerItems(m.view, m.snapshot, m.history, m.spaceRows, m.agentRows)
	m.visible = FilterPickerItems(m.allItems, m.query)
	if m.selectedID == "" || !pickerItemByID(m.visible, m.selectedID) {
		m.selectedID = PreselectPickerItemID(m.view, m.visible, m.history, m.launch)
	}
}

type pickerAcceptedMsg struct{}

type pickerErrorMsg struct{ err error }

func (m pickerModel) acceptCmd() tea.Cmd {
	item, ok := m.selectedItem()
	if !ok {
		return nil
	}
	selectedID := item.ID
	kind := item.Kind
	paneID := item.PaneID
	workspaceID := item.WorkspaceID
	return func() tea.Msg {
		snapshot, witness, err := LoadHerdrSessionSnapshot()
		if err != nil {
			return pickerErrorMsg{err: err}
		}
		var history FocusHistory
		stateDir := pluginStateDir()
		if err := withFocusHistoryLock(stateDir, func() error {
			loaded, loadErr := LoadValidatedFocusHistory(stateDir, witness)
			if loadErr != nil {
				return loadErr
			}
			history = pruneFocusHistory(loaded, snapshot)
			return nil
		}); err != nil {
			return pickerErrorMsg{err: err}
		}
		if kind == pickerKindAgent {
			live, ok := currentAgentLiveID(history, paneID)
			if !ok || live.String() != selectedID {
				return pickerErrorMsg{err: fmt.Errorf("hseh focus: selected occupant was replaced")}
			}
			// Herdr has no atomic conditional focus; a replacement after this
			// snapshot can still receive agent.focus.
			err = FocusHerdrAgent(paneID)
		} else {
			err = FocusHerdrWorkspace(workspaceID)
		}
		if err != nil {
			return pickerErrorMsg{err: err}
		}
		return pickerAcceptedMsg{}
	}
}

func (m pickerModel) View() string {
	if m.width == 0 {
		return "hseh"
	}
	header := clipBlock("hseh  "+m.view+"  /"+m.query, m.width, 1)
	if m.statusErr != "" {
		header = clipBlock("hseh  "+m.view+"  "+m.statusErr, m.width, 1)
	}
	bodyHeight := m.height - 1
	if bodyHeight < 1 {
		bodyHeight = 1
	}
	listWidth := m.width
	showPreview := m.wideEnoughForPreview()
	if showPreview && m.width > 1 {
		listWidth = m.width / 2
		if listWidth < 1 {
			listWidth = 1
		}
	}
	listBody := m.renderList(listWidth, bodyHeight)
	if !showPreview {
		return clipBlock(header+"\n"+listBody, m.width, m.height)
	}
	preview := m.renderPreview(m.width-listWidth, bodyHeight)
	return clipBlock(header+"\n"+lipgloss.JoinHorizontal(lipgloss.Top, listBody, preview), m.width, m.height)
}

func (m pickerModel) renderList(width, height int) string {
	if height < 1 {
		height = 1
	}
	if width < 1 {
		width = 1
	}
	var blocks [][]string
	var selectedBlock int
	if len(m.visible) == 0 {
		blocks = [][]string{wrapDisplayLine("(no results)", width)}
	}
	for _, item := range m.visible {
		prefix := "  "
		if item.ID == m.selectedID {
			prefix = "> "
			selectedBlock = len(blocks)
		}
		block := strings.Join(item.Rows, "\n")
		if block == "" {
			block = item.ID
		}
		var lines []string
		for i, line := range strings.Split(block, "\n") {
			if i == 0 {
				lines = append(lines, wrapDisplayLine(prefix+line, width)...)
			} else {
				lines = append(lines, wrapDisplayLine("  "+line, width)...)
			}
		}
		lines = append(lines, "")
		blocks = append(blocks, lines)
	}
	var all []string
	selectedLine := 0
	lineAt := 0
	for i, block := range blocks {
		if i == selectedBlock {
			selectedLine = lineAt
		}
		all = append(all, block...)
		lineAt += len(block)
	}
	visible := windowAround(all, height, selectedLine)
	return strings.Join(padToHeight(visible, height), "\n")
}

func (m pickerModel) renderPreview(width, height int) string {
	text := m.previewText
	if m.previewErr != "" {
		text = m.previewErr
	}
	if text == "" {
		text = "(preview)"
	}
	return clipBlock(text, width, height)
}

func wrapDisplayLine(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	var lines []string
	remaining := line
	for remaining != "" {
		if lipgloss.Width(remaining) <= width {
			lines = append(lines, remaining)
			break
		}
		cut := 0
		widthSoFar := 0
		for i, r := range remaining {
			w := lipgloss.Width(string(r))
			if widthSoFar+w > width && cut > 0 {
				break
			}
			widthSoFar += w
			cut = i + len(string(r))
		}
		if cut == 0 {
			cut = len(remaining)
		}
		lines = append(lines, remaining[:cut])
		remaining = remaining[cut:]
	}
	if len(lines) == 0 {
		return []string{""}
	}
	return lines
}

func windowAround(lines []string, height, selected int) []string {
	if height < 1 || len(lines) <= height {
		return lines
	}
	if selected < 0 {
		selected = 0
	}
	if selected >= len(lines) {
		selected = len(lines) - 1
	}
	start := selected - height/2
	if start < 0 {
		start = 0
	}
	if start+height > len(lines) {
		start = len(lines) - height
	}
	if selected < start {
		start = selected
	}
	if selected >= start+height {
		start = selected - height + 1
	}
	if start < 0 {
		start = 0
	}
	end := start + height
	if end > len(lines) {
		end = len(lines)
	}
	return lines[start:end]
}

func padToHeight(lines []string, height int) []string {
	for len(lines) < height {
		lines = append(lines, "")
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return lines
}

func clipBlock(text string, width, height int) string {
	if width < 1 {
		width = 1
	}
	if height < 1 {
		height = 1
	}
	var lines []string
	for _, line := range strings.Split(text, "\n") {
		lines = append(lines, wrapDisplayLine(line, width)...)
		if len(lines) >= height {
			break
		}
	}
	return strings.Join(padToHeight(lines, height), "\n")
}

func runPicker(view string) error {
	view, err := parsePickerView(view)
	if err != nil {
		return err
	}
	snapshot, witness, err := LoadHerdrSessionSnapshot()
	if err != nil {
		return err
	}
	stateDir := pluginStateDir()
	var history FocusHistory
	if err := withFocusHistoryLock(stateDir, func() error {
		loaded, loadErr := LoadValidatedFocusHistory(stateDir, witness)
		if loadErr != nil {
			return loadErr
		}
		history = pruneFocusHistory(loaded, snapshot)
		return writeFocusHistoryFile(stateDir, history)
	}); err != nil {
		return err
	}
	spaceRows, agentRows, _ := LoadSidebarTokenRows("")
	poll, _ := LoadPreviewPollInterval()
	wideMin, _ := loadWidePreviewMinColumns()
	model := newPickerModel(view, snapshot, history, spaceRows, agentRows, poll, wideMin)
	_, err = tea.NewProgram(model, tea.WithAltScreen()).Run()
	return err
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"syscall"
)

const workspaceSwitchCycleTimeoutMs = 500

// AgentLiveID is pane id plus occupant generation, not a conversation id.
type AgentLiveID struct {
	PaneID     string `json:"pane_id"`
	Generation int    `json:"generation"`
}

func (id AgentLiveID) String() string {
	return fmt.Sprintf("%s#%d", id.PaneID, id.Generation)
}

// PaneOccupant is the verified agent occupant of one pane.
type PaneOccupant struct {
	Generation   int    `json:"generation"`
	AgentKind    string `json:"agent_kind"`
	SessionValue string `json:"session_value,omitempty"`
}

// WorkspaceSwitchCycle is the in-progress 500ms previous-space cycle.
type WorkspaceSwitchCycle struct {
	Order        []string `json:"order"`
	Target       string   `json:"target"`
	LastSwitchAt int64    `json:"last_switch_at"`
}

// FocusHistory is session-scoped space and agent recency for one proven server.
type FocusHistory struct {
	Witness                ServerContinuityWitness `json:"witness"`
	Spaces                 []string                `json:"spaces"`
	Agents                 []AgentLiveID           `json:"agents,omitempty"`
	Occupants              map[string]PaneOccupant `json:"occupants"`
	LastOccupantGeneration map[string]int          `json:"last_occupant_generation,omitempty"`
	Cycle                  *WorkspaceSwitchCycle   `json:"cycle,omitempty"`
	Pending                []string                `json:"pending,omitempty"`
}

func emptyFocusHistory(witness ServerContinuityWitness) FocusHistory {
	return FocusHistory{
		Witness:                witness,
		Occupants:              map[string]PaneOccupant{},
		LastOccupantGeneration: map[string]int{},
	}
}

func historyStatePath(stateDir string) string {
	return filepath.Join(sessionHistoryDir(stateDir), "history.json")
}

func historyLockPath(stateDir string) string {
	return filepath.Join(sessionHistoryDir(stateDir), "history.lock")
}

func loadFocusHistoryFile(stateDir string) (FocusHistory, error) {
	payload, err := os.ReadFile(historyStatePath(stateDir))
	if err != nil {
		if os.IsNotExist(err) {
			return FocusHistory{Occupants: map[string]PaneOccupant{}}, nil
		}
		return FocusHistory{}, fmt.Errorf("hseh history: read: %w", err)
	}
	var history FocusHistory
	if err := json.Unmarshal(payload, &history); err != nil {
		return FocusHistory{}, fmt.Errorf("hseh history: parse: %w", err)
	}
	if history.Occupants == nil {
		history.Occupants = map[string]PaneOccupant{}
	}
	if history.LastOccupantGeneration == nil {
		history.LastOccupantGeneration = map[string]int{}
	}
	return history, nil
}

func writeFocusHistoryFile(stateDir string, history FocusHistory) error {
	dir := sessionHistoryDir(stateDir)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("hseh history: mkdir: %w", err)
	}
	payload, err := json.Marshal(history)
	if err != nil {
		return fmt.Errorf("hseh history: encode: %w", err)
	}
	temporaryPath := filepath.Join(dir, fmt.Sprintf("history.%d.tmp", os.Getpid()))
	if err := os.WriteFile(temporaryPath, append(payload, '\n'), 0o600); err != nil {
		return fmt.Errorf("hseh history: write: %w", err)
	}
	if err := os.Rename(temporaryPath, historyStatePath(stateDir)); err != nil {
		return fmt.Errorf("hseh history: rename: %w", err)
	}
	return nil
}

func withFocusHistoryLock(stateDir string, fn func() error) error {
	if err := os.MkdirAll(sessionHistoryDir(stateDir), 0o700); err != nil {
		return fmt.Errorf("hseh history: mkdir: %w", err)
	}
	file, err := os.OpenFile(historyLockPath(stateDir), os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return fmt.Errorf("hseh history: lock: %w", err)
	}
	defer file.Close()
	if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX); err != nil {
