package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/BurntSushi/toml"
	"github.com/charmbracelet/lipgloss"
)

type sidebarCell struct {
	Token  string
	Fg     string
	Bold   bool
	Dim    bool
	Styled bool
}

type herdrSidebarFile struct {
	UI struct {
		StatusIndicators string `toml:"status_indicators"`
		Sidebar          struct {
			Agents struct {
				Rows        [][]any            `toml:"rows"`
				RowsByAgent map[string][][]any `toml:"rows_by_agent"`
			} `toml:"agents"`
			Spaces struct {
				Rows [][]any `toml:"rows"`
			} `toml:"spaces"`
		} `toml:"sidebar"`
	} `toml:"ui"`
}

func defaultAgentSidebarRows() [][]string {
	return [][]string{{"state_icon", "machine", "workspace", "tab"}, {"agent"}}
}

func defaultSpaceSidebarRows() [][]string {
	return [][]string{{"state_icon", "workspace"}, {"branch", "git_status"}}
}

var lastSidebarByAgent = map[string][][]sidebarCell{}
var lastSidebarStatusMode = "dots"

// LoadSidebarTokenRows reads ui.sidebar rows, rows_by_agent, and token styles.
func LoadSidebarTokenRows(configPath string) (spaceRows, agentRows [][]string, errs []string) {
	spaceCells, agentCells, byAgent, mode, errs := loadSidebarCells(configPath)
	lastSidebarByAgent = byAgent
	lastSidebarStatusMode = mode
	return stringifySidebarRows(spaceCells), stringifySidebarRows(agentCells), errs
}

func loadSidebarCells(configPath string) (spaceRows, agentRows [][]sidebarCell, byAgent map[string][][]sidebarCell, mode string, errs []string) {
	spaceRows = parseSidebarCellsFromStrings(defaultSpaceSidebarRows())
	agentRows = parseSidebarCellsFromStrings(defaultAgentSidebarRows())
	byAgent = map[string][][]sidebarCell{}
	mode = "dots"
	if configPath == "" {
		configPath = herdrConfigPath()
	}
	payload, err := os.ReadFile(configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return spaceRows, agentRows, byAgent, mode, nil
		}
		return spaceRows, agentRows, byAgent, mode, []string{fmt.Sprintf("hseh sidebar: read %s: %v", configPath, err)}
	}
	var file herdrSidebarFile
	if err := toml.Unmarshal(payload, &file); err != nil {
		return spaceRows, agentRows, byAgent, mode, []string{fmt.Sprintf("hseh sidebar: parse %s: %v", configPath, err)}
	}
	if file.UI.StatusIndicators == "symbols" {
		mode = "symbols"
	}
	if parsed := parseSidebarCells(file.UI.Sidebar.Spaces.Rows); len(parsed) > 0 {
		spaceRows = parsed
	}
	if parsed := parseSidebarCells(file.UI.Sidebar.Agents.Rows); len(parsed) > 0 {
		agentRows = parsed
	}
	for agentID, raw := range file.UI.Sidebar.Agents.RowsByAgent {
		if parsed := parseSidebarCells(raw); len(parsed) > 0 {
			byAgent[agentID] = parsed
		}
	}
	return spaceRows, agentRows, byAgent, mode, nil
}

func stringifySidebarRows(rows [][]sidebarCell) [][]string {
	var out [][]string
	for _, row := range rows {
		var tokens []string
		for _, cell := range row {
			tokens = append(tokens, cell.Token)
		}
		out = append(out, tokens)
	}
	return out
}

func parseSidebarCellsFromStrings(rows [][]string) [][]sidebarCell {
	var out [][]sidebarCell
	for _, row := range rows {
		var cells []sidebarCell
		for _, token := range row {
			cells = append(cells, sidebarCell{Token: token})
		}
		out = append(out, cells)
	}
	return out
}

func herdrConfigPath() string {
	if path := os.Getenv("HERDR_CONFIG_PATH"); path != "" {
		return path
	}
	if dir := os.Getenv("XDG_CONFIG_HOME"); dir != "" {
		return filepath.Join(dir, "herdr", "config.toml")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config", "herdr", "config.toml")
}

func parseSidebarCells(raw [][]any) [][]sidebarCell {
	var rows [][]sidebarCell
	for _, row := range raw {
		var cells []sidebarCell
		for _, item := range row {
			switch value := item.(type) {
			case string:
				if value != "" {
					cells = append(cells, sidebarCell{Token: value})
				}
			case map[string]any:
				token, _ := value["token"].(string)
				if token == "" {
					continue
				}
				cell := sidebarCell{Token: token, Styled: true}
				if fg, ok := value["fg"].(string); ok {
					cell.Fg = fg
				}
				if bold, ok := value["bold"].(bool); ok {
					cell.Bold = bold
				}
				if dim, ok := value["dim"].(bool); ok {
					cell.Dim = dim
				}
				cells = append(cells, cell)
			}
		}
		if len(cells) > 0 {
			rows = append(rows, cells)
