func stateIconGlyph(status, mode string) string {
	if mode == "symbols" {
		switch status {
		case "blocked":
			return "!"
		case "done":
			return "+"
		case "working":
			return "*"
		case "idle":
			return "-"
		default:
			return "?"
		}
	}
	return "●"
}

func stateIconColor(status string) string {
	switch status {
	case "blocked":
		return "#f38ba8"
	case "done":
		return "#f9e2af"
	case "working":
		return "#89b4fa"
	case "idle":
		return "#a6e3a1"
	default:
		return "#6c7086"
	}
}

func styleTokenValue(cell sidebarCell, value, status string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}
	style := lipgloss.NewStyle()
	if cell.Token == "state_icon" {
		style = style.Foreground(lipgloss.Color(stateIconColor(status)))
	}
	if cell.Styled && cell.Fg != "" {
		style = style.Foreground(lipgloss.Color(cell.Fg))
	}
	if cell.Styled && cell.Bold {
		style = style.Bold(true)
	}
	if cell.Styled && cell.Dim {
		style = style.Faint(true)
	}
	if cell.Token == "state_icon" || cell.Styled {
		return style.Render(value)
	}
	return value
}

