	t.Setenv("HERDR_SESSION", "hseh-test")
	m := pickerModel{widePreviewMinCols: 40, selectedID: "w2", visible: []PickerItem{{ID: "w2", PreviewPane: "w2:p1"}}}
	next, cmd := m.Update(tea.WindowSizeMsg{Width: 100, Height: 30})
	got := next.(pickerModel)
