package main

import (
	"fmt"
	"path/filepath"
	"sort"
	"strings"
)

const (
	spaceOpenActionFocus  = "focus"
	spaceOpenActionAdopt  = "adopt"
	spaceOpenActionCreate = "create"
)

// SpaceOpenResult is the caller-visible outcome of create-or-focus.
type SpaceOpenResult struct {
	Action            string
	WorkspaceID       string
	SubmittedCommands int
	DefinitionID      string
	ResolvedDir       string
}

func withSpaceOpenLock(fn func() error) error {
	return withExclusiveFileLock(spaceOpenLockPath(pluginStateDir()), fn)
}

func workspaceGitCheckoutDir(workspace HerdrWorkspaceRow) string {
	if workspace.Worktree == nil {
		return ""
	}
	path := strings.TrimSpace(workspace.Worktree.CheckoutPath)
	if path == "" {
		return ""
	}
	canonical, err := canonicalExistingDir(path)
	if err != nil {
		return ""
	}
	return canonical
}

func workspaceUniformPaneDir(snapshot HerdrSessionSnapshot, workspaceID string) (string, bool) {
	var dir string
	found := false
	for _, pane := range snapshot.Panes {
		if pane.WorkspaceID != workspaceID {
			continue
		}
		raw := strings.TrimSpace(pane.Cwd)
		if raw == "" {
			return "", false
		}
		canonical, err := canonicalExistingDir(raw)
		if err != nil {
			return "", false
		}
		if !found {
			dir = canonical
			found = true
			continue
		}
		if canonical != dir {
			return "", false
		}
	}
	if !found {
		return "", false
	}
	return dir, true
}

func workspaceDirectorySignal(snapshot HerdrSessionSnapshot, workspace HerdrWorkspaceRow) (string, bool) {
	if checkout := workspaceGitCheckoutDir(workspace); checkout != "" {
		return checkout, true
	}
	return workspaceUniformPaneDir(snapshot, workspace.WorkspaceID)
}

func eligibleAdoptionWorkspaceIDs(snapshot HerdrSessionSnapshot, history FocusHistory, state SpaceAssociationState, definitionID, resolvedDir string) []string {
	var eligible []string
	for _, workspace := range snapshot.Workspaces {
		if workspaceAssociatedToOtherDefinition(state, workspace.WorkspaceID, definitionID, resolvedDir) {
			continue
		}
		dir, ok := workspaceDirectorySignal(snapshot, workspace)
		if !ok || dir != resolvedDir {
			continue
		}
		eligible = append(eligible, workspace.WorkspaceID)
	}
	indexOf := map[string]int{}
	for i, id := range history.Spaces {
		indexOf[id] = i
	}
	sort.SliceStable(eligible, func(i, j int) bool {
		left, leftOK := indexOf[eligible[i]]
		right, rightOK := indexOf[eligible[j]]
		if leftOK && rightOK {
			return left < right
		}
		if leftOK {
			return true
		}
		if rightOK {
			return false
		}
		return i < j
	})
	return eligible
}

func persistCreatedAssociation(stateDir string, state SpaceAssociationState, record SpaceAssociationRecord) error {
	state = upsertSpaceAssociation(state, record)
	return writeSpaceAssociationFile(stateDir, state)
}

func openReusableSpaceLocked(definitionID string) (SpaceOpenResult, error) {
	defs, errs := LoadSpaceDefinitions(spaceDefinitionsDir())
	def, ok := findSpaceDefinitionByID(defs, definitionID)
	if !ok {
		if len(errs) > 0 {
			return SpaceOpenResult{}, fmt.Errorf("hseh open %s: not found (%s)", definitionID, strings.Join(errs, "; "))
		}
		return SpaceOpenResult{}, fmt.Errorf("hseh open: definition %s not found", definitionID)
	}
	snapshot, witness, err := LoadHerdrSessionSnapshot()
	if err != nil {
		return SpaceOpenResult{}, err
	}
	stateDir := pluginStateDir()
	state, err := loadSpaceAssociationsForSameServer(stateDir, witness)
	if err != nil {
		return SpaceOpenResult{}, err
	}
	history, err := LoadPrunedFocusHistory(snapshot, witness)
	if err != nil {
		return SpaceOpenResult{}, err
	}
	if workspaceID, ok := exactLiveAssociation(state, snapshot, def.ID, def.ResolvedDir); ok {
		if err := FocusHerdrWorkspace(workspaceID); err != nil {
			return SpaceOpenResult{}, err
		}
		return SpaceOpenResult{Action: spaceOpenActionFocus, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
	}
	eligible := eligibleAdoptionWorkspaceIDs(snapshot, history, state, def.ID, def.ResolvedDir)
	if len(eligible) > 0 {
		workspaceID := eligible[0]
		state = upsertSpaceAssociation(state, SpaceAssociationRecord{
			DefinitionID: def.ID,
			ResolvedDir:  def.ResolvedDir,
			WorkspaceID:  workspaceID,
		})
		if err := writeSpaceAssociationFile(stateDir, state); err != nil {
			return SpaceOpenResult{}, fmt.Errorf("hseh open %s: persist adoption: %w", def.ID, err)
		}
		if err := FocusHerdrWorkspace(workspaceID); err != nil {
			return SpaceOpenResult{}, err
		}
		return SpaceOpenResult{Action: spaceOpenActionAdopt, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
	}
	if err := preflightSpaceDefinitionDirs(def); err != nil {
		return SpaceOpenResult{}, err
	}
	workspaceID, rootTabID, rootPaneID, err := createHerdrWorkspace(def.ResolvedDir, def.Name, true)
	if err != nil {
		return SpaceOpenResult{}, fmt.Errorf("hseh create %s: workspace.create: %w", def.ID, err)
	}
	record := SpaceAssociationRecord{DefinitionID: def.ID, ResolvedDir: def.ResolvedDir, WorkspaceID: workspaceID}
	if err := persistCreatedAssociation(stateDir, state, record); err != nil {
		return SpaceOpenResult{Action: spaceOpenActionCreate, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, fmt.Errorf("hseh create %s: persist association after workspace.create %s: %w", def.ID, workspaceID, err)
	}
	submitted, err := layoutReusableSpace(def, workspaceID, rootTabID, rootPaneID)
	result := SpaceOpenResult{Action: spaceOpenActionCreate, WorkspaceID: workspaceID, SubmittedCommands: submitted, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}
	if err != nil {
		return result, err
	}
	return result, nil
}

// OpenReusableSpace focuses, adopts, or creates a definition in the current Herdr server lifetime.
func OpenReusableSpace(definitionID string) (SpaceOpenResult, error) {
	definitionID = strings.TrimSpace(definitionID)
	if definitionID == "" {
		return SpaceOpenResult{}, fmt.Errorf("hseh open: definition id is required")
	}
	var result SpaceOpenResult
	err := withSpaceOpenLock(func() error {
		var innerErr error
		result, innerErr = openReusableSpaceLocked(definitionID)
		return innerErr
	})
	return result, err
}

func runOpenReusableSpace(definitionID string) error {
	result, err := OpenReusableSpace(definitionID)
	if err != nil {
		return err
	}
	fmt.Printf("opened %s %s %s\n", result.Action, result.DefinitionID, result.WorkspaceID)
	return nil
}

func definitionPickerItem(def SpaceDefinition) PickerItem {
	rows := []string{def.Name}
	if strings.TrimSpace(def.Description) != "" {
		rows = append(rows, def.Description)
	}
	if def.ResolvedDir != "" {
		rows = append(rows, def.ResolvedDir)
	} else {
		rows = append(rows, def.WorkingDir)
	}
	search := strings.Join(append(rows, def.SourceFile, filepath.Base(def.SourceFile)), " ")
	return PickerItem{
		Kind:        pickerKindDefinition,
		ID:          def.ID,
		Label:       def.Name,
		Rows:        rows,
		DisplayRows: rows,
		SearchText:  search,
		PreviewText: spaceDefinitionPreviewText(def),
	}
}

func appendUnopenedDefinitionItems(items []PickerItem, view string, snapshot HerdrSessionSnapshot, definitions []SpaceDefinition, records []SpaceAssociationRecord) []PickerItem {
	if view == pickerViewAgents {
		return items
	}
	openKeys := associatedLiveDefinitionKeys(SpaceAssociationState{Records: records}, snapshot)
	var extra []PickerItem
	for _, def := range definitions {
		if openKeys[associationIdentityKey(def.ID, def.ResolvedDir)] {
			continue
		}
		extra = append(extra, definitionPickerItem(def))
	}
	sort.SliceStable(extra, func(i, j int) bool { return extra[i].Label < extra[j].Label })
	return append(items, extra...)
}

package main

import (
	"fmt"
	"os"
	"strings"
)

type herdrWorkspaceCreated struct {
	Type      string `json:"type"`
	Workspace struct {
		WorkspaceID string `json:"workspace_id"`
	} `json:"workspace"`
	Tab struct {
		TabID string `json:"tab_id"`
	} `json:"tab"`
	RootPane struct {
		PaneID string `json:"pane_id"`
	} `json:"root_pane"`
}

type herdrTabCreated struct {
	Type string `json:"type"`
	Tab  struct {
		TabID string `json:"tab_id"`
	} `json:"tab"`
	RootPane struct {
		PaneID string `json:"pane_id"`
	} `json:"root_pane"`
}

type herdrPaneSplitResult struct {
	Type string `json:"type"`
	Pane struct {
		PaneID string `json:"pane_id"`
	} `json:"pane"`
}

func createHerdrWorkspace(cwd, label string, focus bool) (workspaceID, tabID, paneID string, err error) {
	var out herdrWorkspaceCreated
	_, err = CallHerdrMethod("workspace.create", map[string]any{
		"cwd":   cwd,
		"label": label,
		"focus": focus,
	}, &out)
	if err != nil {
		return "", "", "", err
	}
	if out.Workspace.WorkspaceID == "" || out.Tab.TabID == "" || out.RootPane.PaneID == "" {
		return "", "", "", fmt.Errorf("hseh create: workspace.create missing ids")
	}
	return out.Workspace.WorkspaceID, out.Tab.TabID, out.RootPane.PaneID, nil
}

func createHerdrTab(workspaceID, label, cwd string, focus bool) (tabID, paneID string, err error) {
	params := map[string]any{
		"workspace_id": workspaceID,
		"label":        label,
		"focus":        focus,
	}
	if strings.TrimSpace(cwd) != "" {
		params["cwd"] = cwd
	}
	var out herdrTabCreated
	_, err = CallHerdrMethod("tab.create", params, &out)
	if err != nil {
		return "", "", err
	}
	if out.Tab.TabID == "" || out.RootPane.PaneID == "" {
		return "", "", fmt.Errorf("hseh create: tab.create missing ids")
	}
	return out.Tab.TabID, out.RootPane.PaneID, nil
}

func renameHerdrTab(tabID, label string) error {
	var result map[string]any
	_, err := CallHerdrMethod("tab.rename", map[string]any{"tab_id": tabID, "label": label}, &result)
	return err
}

func closeHerdrTab(tabID string) error {
	var result map[string]any
	_, err := CallHerdrMethod("tab.close", map[string]any{"tab_id": tabID}, &result)
	return err
}

func splitHerdrPane(targetPaneID, direction string, ratio float64, cwd string, focus bool) (string, error) {
	params := map[string]any{
		"target_pane_id": targetPaneID,
		"direction":      direction,
		"focus":          focus,
	}
	if ratio > 0 {
		params["ratio"] = ratio
	}
	if strings.TrimSpace(cwd) != "" {
		params["cwd"] = cwd
	}
	var out herdrPaneSplitResult
	_, err := CallHerdrMethod("pane.split", params, &out)
	if err != nil {
		return "", err
	}
	if out.Pane.PaneID == "" {
		return "", fmt.Errorf("hseh create: pane.split missing pane_id")
	}
	return out.Pane.PaneID, nil
}

func renameHerdrPane(paneID, label string) error {
	var result map[string]any
	_, err := CallHerdrMethod("pane.rename", map[string]any{"pane_id": paneID, "label": label}, &result)
	return err
}

func submitHerdrPaneCommand(paneID, command string) error {
	var result map[string]any
	_, err := CallHerdrMethod("pane.send_input", map[string]any{
		"pane_id": paneID,
		"text":    command,
		"keys":    []string{"Enter"},
	}, &result)
	return err
}

func preflightSpaceDefinitionDirs(def SpaceDefinition) error {
	info, err := os.Stat(def.ResolvedDir)
	if err != nil || !info.IsDir() {
		return fmt.Errorf("hseh create %s: working directory does not exist: %s", def.ID, def.ResolvedDir)
	}
	if err := checkSpaceDefinitionTabDirs(def.ResolvedDir, def.Tabs); err != nil {
		return fmt.Errorf("hseh create %s: %w", def.ID, err)
	}
	return nil
}

type pendingPaneCommand struct {
	paneID  string
	command string
}

func layoutReusableSpace(def SpaceDefinition, workspaceID, rootTabID, rootPaneID string) (int, error) {
	dirs, err := resolveSpaceDefinitionPaneDirs(def.ResolvedDir, def.Tabs)
	if err != nil {
		return 0, fmt.Errorf("hseh create %s: %w", def.ID, err)
	}
	var runs []pendingPaneCommand
	for i, tab := range def.Tabs {
		tabRoot := rootPaneID
		if i == 0 {
			if dir := dirs[i][0]; dir != "" && dir != def.ResolvedDir {
				_, tabRoot, err = createHerdrTab(workspaceID, tab.Name, dir, true)
				if err != nil {
					return 0, fmt.Errorf("hseh create %s: tab.create %q: %w", def.ID, tab.Name, err)
				}
				if err = closeHerdrTab(rootTabID); err != nil {
					return 0, fmt.Errorf("hseh create %s: close replaced root tab: %w", def.ID, err)
				}
			} else if err = renameHerdrTab(rootTabID, tab.Name); err != nil {
				return 0, fmt.Errorf("hseh create %s: tab.rename %q: %w", def.ID, tab.Name, err)
			}
		} else {
			_, tabRoot, err = createHerdrTab(workspaceID, tab.Name, dirs[i][0], false)
			if err != nil {
				return 0, fmt.Errorf("hseh create %s: tab.create %q: %w", def.ID, tab.Name, err)
			}
		}
		prev := tabRoot
		for j, pane := range tab.effectivePanes() {
			paneID := tabRoot
			if j > 0 {
				paneID, err = splitHerdrPane(prev, pane.Split, pane.splitRatio(), dirs[i][j], false)
				if err != nil {
					return 0, fmt.Errorf("hseh create %s: pane.split tab %q pane %d: %w", def.ID, tab.Name, j+1, err)
				}
			}
			if lbl := strings.TrimSpace(pane.Label); lbl != "" {
				if err := renameHerdrPane(paneID, lbl); err != nil {
					return 0, fmt.Errorf("hseh create %s: pane.rename tab %q pane %d: %w", def.ID, tab.Name, j+1, err)
				}
			}
			if strings.TrimSpace(pane.Command) != "" {
				runs = append(runs, pendingPaneCommand{paneID: paneID, command: pane.Command})
			}
			prev = paneID
		}
	}
	for _, run := range runs {
		if err := submitHerdrPaneCommand(run.paneID, run.command); err != nil {
			return 0, fmt.Errorf("hseh create %s: pane.send_input %s: %w", def.ID, run.paneID, err)
		}
	}
	return len(runs), nil
}

package main

import (
	"bytes"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode"

	"github.com/BurntSushi/toml"
)

const (
	spaceDefinitionPromptDir  = "{prompt}"
	maxPanesPerTab            = 4
	spaceDefinitionSplitDown  = "down"
	spaceDefinitionSplitRight = "right"
)

// SpaceDefinition is one fixed-directory reusable space from a TOML file.
type SpaceDefinition struct {
	ID          string               `toml:"id"`
	Name        string               `toml:"name"`
	Description string               `toml:"description"`
	WorkingDir  string               `toml:"working_dir"`
	Tabs        []SpaceDefinitionTab `toml:"tabs"`
	SourceFile  string               `toml:"-"`
	ResolvedDir string               `toml:"-"`
}

// SpaceDefinitionTab is one tab in a reusable space definition.
type SpaceDefinitionTab struct {
	Name       string                `toml:"name"`
	Command    string                `toml:"command"`
	WorkingDir string                `toml:"working_dir"`
	Panes      []SpaceDefinitionPane `toml:"panes"`
}

// SpaceDefinitionPane is one pane in a tab. Split and Ratio apply after the root pane.
type SpaceDefinitionPane struct {
	Command    string  `toml:"command"`
	Split      string  `toml:"split"`
	Label      string  `toml:"label"`
	Ratio      float64 `toml:"ratio"`
	WorkingDir string  `toml:"working_dir"`
}

func newSpaceDefinitionID() (string, error) {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", fmt.Errorf("hseh definition: generate id: %w", err)
	}
	return hex.EncodeToString(raw[:]), nil
}

func decodeSpaceDefinitionTOML(payload []byte) (SpaceDefinition, toml.MetaData, error) {
	var def SpaceDefinition
	meta, err := toml.Decode(string(payload), &def)
	if err != nil {
		return SpaceDefinition{}, meta, err
	}
	return def, meta, nil
}

func spaceDefinitionHasTopLevelID(meta toml.MetaData) bool {
	return meta.IsDefined("id")
}

func validateSpaceDefinitionIDValue(id string) error {
	trimmed := strings.TrimSpace(id)
	if trimmed == "" {
		return fmt.Errorf("id is empty")
	}
	if trimmed != id {
		return fmt.Errorf("id has surrounding whitespace")
	}
	for _, r := range id {
		if unicode.IsSpace(r) || !unicode.IsPrint(r) {
			return fmt.Errorf("id contains whitespace or non-printable characters")
		}
	}
	return nil
}

func validateSpaceDefinition(def SpaceDefinition) error {
	if strings.TrimSpace(def.Name) == "" {
		return fmt.Errorf("hseh definition %s: name is required", def.SourceFile)
	}
	workingDir := strings.TrimSpace(def.WorkingDir)
	if workingDir == "" {
		return fmt.Errorf("hseh definition %q (%s): working_dir is required", def.Name, def.SourceFile)
	}
	if workingDir == spaceDefinitionPromptDir {
		return fmt.Errorf("hseh definition %q (%s): working_dir {prompt} is not supported", def.Name, def.SourceFile)
	}
	if len(def.Tabs) == 0 {
		return fmt.Errorf("hseh definition %q (%s): needs at least one [[tabs]] entry", def.Name, def.SourceFile)
	}
	return validateSpaceDefinitionTabs(def.Name, def.SourceFile, def.Tabs)
}

// validateSpaceDefinitionTabs copies Herdr Plus tab rules: name required, command or panes, at most 4 panes,
// split down/right, omitted ratio is an even split. See third_party/herdr-plus/NOTICE.
func validateSpaceDefinitionTabs(label, source string, tabs []SpaceDefinitionTab) error {
	for i, tab := range tabs {
		if strings.TrimSpace(tab.Name) == "" {
			return fmt.Errorf("%q (%s): tab %d is missing a name", label, source, i+1)
		}
		if len(tab.Panes) > 0 && strings.TrimSpace(tab.Command) != "" {
			return fmt.Errorf("%q (%s): tab %q sets both command and [[tabs.panes]]; use one or the other", label, source, tab.Name)
		}
		if len(tab.Panes) > maxPanesPerTab {
			return fmt.Errorf("%q (%s): tab %q has %d panes; at most %d are allowed", label, source, tab.Name, len(tab.Panes), maxPanesPerTab)
		}
		for j, pane := range tab.Panes {
			if j == 0 {
				continue
			}
			switch pane.Split {
			case "", spaceDefinitionSplitDown, spaceDefinitionSplitRight:
			default:
				return fmt.Errorf("%q (%s): tab %q pane %d has split %q; must be %q or %q", label, source, tab.Name, j+1, pane.Split, spaceDefinitionSplitDown, spaceDefinitionSplitRight)
			}
			if pane.Ratio < 0 || pane.Ratio >= 1 {
				return fmt.Errorf("%q (%s): tab %q pane %d has ratio %v; must be greater than 0 and less than 1", label, source, tab.Name, j+1, pane.Ratio)
			}
		}
	}
	return nil
}

func spaceDefinitionFileWritable(path string) error {
	file, err := os.OpenFile(path, os.O_RDWR, 0)
	if err != nil {
		return fmt.Errorf("hseh definition: %s is not writable: %w", path, err)
	}
	return file.Close()
}

func writeSpaceDefinitionBytes(path string, payload []byte) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_TRUNC, 0)
	if err != nil {
		return fmt.Errorf("hseh definition: write %s: %w", path, err)
	}
	_, writeErr := file.Write(payload)
	closeErr := file.Close()
	if writeErr != nil {
		return fmt.Errorf("hseh definition: write %s: %w", path, writeErr)
	}
	if closeErr != nil {
		return fmt.Errorf("hseh definition: close %s: %w", path, closeErr)
	}
	return nil
}

func insertMissingSpaceDefinitionID(path string, original []byte) (string, []byte, error) {
	id, err := newSpaceDefinitionID()
	if err != nil {
		return "", nil, err
	}
	inserted := append([]byte("id = \""+id+"\"\n"), original...)
	if err := writeSpaceDefinitionBytes(path, inserted); err != nil {
		return "", nil, err
	}
	return id, inserted, nil
}

func loadSpaceDefinitionFromBytes(path string, payload []byte) (SpaceDefinition, toml.MetaData, error) {
	def, meta, err := decodeSpaceDefinitionTOML(payload)
	if err != nil {
		return SpaceDefinition{}, meta, fmt.Errorf("hseh definition: parse %s: %w", filepath.Base(path), err)
	}
	def.SourceFile = filepath.Base(path)
	return def, meta, nil
}

func ensureSpaceDefinitionIDLocked(path string) (SpaceDefinition, error) {
	payload, err := os.ReadFile(path)
	if err != nil {
		return SpaceDefinition{}, fmt.Errorf("hseh definition: read %s: %w", path, err)
	}
	def, meta, err := loadSpaceDefinitionFromBytes(path, payload)
	if err != nil {
		return SpaceDefinition{}, err
	}
	if spaceDefinitionHasTopLevelID(meta) {
		if err := validateSpaceDefinitionIDValue(def.ID); err != nil {
			return SpaceDefinition{}, fmt.Errorf("hseh definition %s: %w", def.SourceFile, err)
		}
		if err := validateSpaceDefinition(def); err != nil {
			return SpaceDefinition{}, err
		}
		return def, nil
	}
	if err := validateSpaceDefinition(def); err != nil {
		return SpaceDefinition{}, err
	}
	if err := spaceDefinitionFileWritable(path); err != nil {
		return SpaceDefinition{}, err
	}
	id, _, err := insertMissingSpaceDefinitionID(path, payload)
	if err != nil {
		return SpaceDefinition{}, err
	}
	def.ID = id
	return def, nil
}

// EnsureSpaceDefinitionID inserts a missing top-level id using TOML metadata, not a line regex.
func EnsureSpaceDefinitionID(path string) (SpaceDefinition, error) {
	var def SpaceDefinition
	err := withExclusiveFileLock(path+".lock", func() error {
		var innerErr error
		def, innerErr = ensureSpaceDefinitionIDLocked(path)
		return innerErr
	})
	return def, err
}

func resolveSpaceDefinitionDir(def SpaceDefinition) (string, error) {
	expanded, err := expandSpaceDefinitionPath(def.WorkingDir)
	if err != nil {
		return "", fmt.Errorf("hseh definition %q (%s): working_dir: %w", def.Name, def.SourceFile, err)
	}
	abs, err := filepath.Abs(expanded)
	if err != nil {
		return "", fmt.Errorf("hseh definition %q (%s): working_dir: %w", def.Name, def.SourceFile, err)
	}
	if resolved, err := filepath.EvalSymlinks(abs); err == nil {
		return resolved, nil
	}
	return filepath.Clean(abs), nil
}

// LoadSpaceDefinitions reads valid *.toml files from the plugin spaces directory.
func LoadSpaceDefinitions(dir string) ([]SpaceDefinition, []string) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, []string{fmt.Sprintf("hseh definition: read %s: %v", dir, err)}
	}
	type loaded struct {
		def  SpaceDefinition
		file string
	}
	var loadedDefs []loaded
	var errs []string
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".toml") {
			continue
		}
		path := filepath.Join(dir, entry.Name())
		def, err := EnsureSpaceDefinitionID(path)
		if err != nil {
			errs = append(errs, err.Error())
			continue
		}
		resolved, err := resolveSpaceDefinitionDir(def)
		if err != nil {
			errs = append(errs, err.Error())
			continue
		}
		def.ResolvedDir = resolved
		loadedDefs = append(loadedDefs, loaded{def: def, file: entry.Name()})
	}
	byID := map[string][]loaded{}
	for _, item := range loadedDefs {
		byID[item.def.ID] = append(byID[item.def.ID], item)
	}
	var defs []SpaceDefinition
	for id, items := range byID {
		if len(items) > 1 {
			var files []string
			for _, item := range items {
				files = append(files, item.file)
			}
			errs = append(errs, fmt.Sprintf("hseh definition: duplicate id %s in %s", id, strings.Join(files, ", ")))
			continue
		}
		defs = append(defs, items[0].def)
	}
	return defs, errs
}

func findSpaceDefinitionByID(defs []SpaceDefinition, id string) (SpaceDefinition, bool) {
	for _, def := range defs {
		if def.ID == id {
			return def, true
		}
	}
	return SpaceDefinition{}, false
}

func spaceDefinitionPreviewText(def SpaceDefinition) string {
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s\n%s\n", def.Name, def.ResolvedDir)
	if strings.TrimSpace(def.Description) != "" {
		fmt.Fprintf(&b, "%s\n", def.Description)
	}
	for _, tab := range def.Tabs {
		fmt.Fprintf(&b, "tab %s\n", tab.Name)
		for _, pane := range tab.effectivePanes() {
			cmd := strings.TrimSpace(pane.Command)
			if cmd == "" {
				cmd = "(shell)"
			}
			fmt.Fprintf(&b, "  %s\n", cmd)
		}
	}
	return strings.TrimRight(b.String(), "\n")
}

