package main

import (
	"strings"

	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"
)

func (m pickerModel) View() string {
	if m.width == 0 {
		return "hseh"
	}
	headerText := "hseh  " + m.view + "  /" + m.query
	if m.statusErr != "" {
		headerText = "hseh  " + m.view + "  " + m.statusErr
	}
	header := padDisplayWidth(headerText, m.width)
	bodyHeight := m.height - 1
	if bodyHeight < 1 {
		bodyHeight = 1
	}
	listWidth := m.width
	showPreview := m.wideEnoughForPreview()
	if showPreview && m.width > 1 {
		listWidth = m.width / 2
		if listWidth < 1 {
			listWidth = 1
		}
	}
	listBody := m.renderList(listWidth, bodyHeight)
	if !showPreview {
		return header + "\n" + listBody
	}
	previewWidth := m.width - listWidth
	if previewWidth < 1 {
		previewWidth = 1
	}
	preview := m.renderPreview(previewWidth, bodyHeight)
	listLines := strings.Split(listBody, "\n")
	prevLines := strings.Split(preview, "\n")
	var lines []string
	for i := 0; i < bodyHeight; i++ {
		left, right := "", ""
		if i < len(listLines) {
			left = listLines[i]
		}
		if i < len(prevLines) {
			right = prevLines[i]
		}
		lines = append(lines, padDisplayWidth(left, listWidth)+padDisplayWidth(right, previewWidth))
	}
	return header + "\n" + strings.Join(lines, "\n")
}

func (m pickerModel) renderList(width, height int) string {
	if height < 1 {
		height = 1
	}
	if width < 1 {
		width = 1
	}
	var blocks [][]string
	var selectedBlock int
	if len(m.visible) == 0 {
		blocks = [][]string{wrapDisplayLine("(no results)", width)}
	}
	for _, item := range m.visible {
		prefix := "  "
		if item.ID == m.selectedID {
			prefix = "> "
			selectedBlock = len(blocks)
		}
		block := strings.Join(item.DisplayRows, "\n")
		if block == "" {
			block = strings.Join(item.Rows, "\n")
		}
		if block == "" {
			block = item.ID
		}
		var lines []string
		for i, line := range strings.Split(block, "\n") {
			if i == 0 {
				lines = append(lines, wrapDisplayLine(prefix+line, width)...)
			} else {
				lines = append(lines, wrapDisplayLine("  "+line, width)...)
			}
		}
		lines = append(lines, "")
		blocks = append(blocks, lines)
	}
	var all []string
	selectedLine := 0
	lineAt := 0
	for i, block := range blocks {
		if i == selectedBlock {
			selectedLine = lineAt
		}
		all = append(all, block...)
		lineAt += len(block)
	}
	visible := windowAround(all, height, selectedLine)
	for i, line := range visible {
		visible[i] = padDisplayWidth(line, width)
	}
	return strings.Join(padToHeight(visible, height), "\n")
}

func (m pickerModel) renderPreview(width, height int) string {
	text := m.previewText
	if m.previewErr != "" {
		text = m.previewErr
	}
	if text == "" {
		text = "(preview)"
	}
	return clipBlock(text, width, height)
}

func wrapDisplayLine(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	wrapped := ansi.Hardwrap(line, width, false)
	if wrapped == "" {
		return []string{""}
	}
	return strings.Split(wrapped, "\n")
}

func padDisplayWidth(line string, width int) string {
	if width <= 0 {
		return ""
	}
	line = ansi.Truncate(line, width, "")
	return lipgloss.NewStyle().Width(width).MaxHeight(1).Render(line)
}

func windowAround(lines []string, height, selected int) []string {
	if height < 1 || len(lines) <= height {
		return lines
	}
	if selected < 0 {
		selected = 0
	}
	if selected >= len(lines) {
		selected = len(lines) - 1
	}
	start := selected
	if start+height > len(lines) {
		start = len(lines) - height
	}
	if start < 0 {
		start = 0
	}
	if selected >= start+height {
		start = selected - height + 1
	}
	if start < 0 {
		start = 0
	}
	end := start + height
	if end > len(lines) {
		end = len(lines)
	}
	return lines[start:end]
}

func padToHeight(lines []string, height int) []string {
	for len(lines) < height {
		lines = append(lines, "")
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return lines
}

func clipBlock(text string, width, height int) string {
	if width < 1 {
		width = 1
	}
	if height < 1 {
		height = 1
	}
	var lines []string
	for _, line := range strings.Split(text, "\n") {
		lines = append(lines, wrapDisplayLine(line, width)...)
		if len(lines) >= height {
			break
		}
	}
	for i, line := range lines {
		if i >= height {
			break
		}
		lines[i] = padDisplayWidth(line, width)
	}
	return strings.Join(padToHeight(lines, height), "\n")
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// errUnresolvedSpaceAssociationRestart is the not-yet-approved restart branch.
var errUnresolvedSpaceAssociationRestart = errors.New("hseh open: stored associations are from a different Herdr server generation; restart handling is not approved")

// SpaceAssociationRecord is one definition-id + resolved-dir to live workspace link.
type SpaceAssociationRecord struct {
	DefinitionID string `json:"definition_id"`
	ResolvedDir  string `json:"resolved_dir"`
	WorkspaceID  string `json:"workspace_id"`
}

// SpaceAssociationState is session-scoped association provenance for one proven server.
type SpaceAssociationState struct {
	Witness ServerContinuityWitness  `json:"witness"`
	Records []SpaceAssociationRecord `json:"records"`
}

func spaceAssociationStatePath(stateDir string) string {
	return filepath.Join(sessionHistoryDir(stateDir), "associations.json")
}

func spaceOpenLockPath(stateDir string) string {
	return filepath.Join(sessionHistoryDir(stateDir), "space-open.lock")
}

func associationIdentityKey(definitionID, resolvedDir string) string {
	return definitionID + "\n" + resolvedDir
}

func loadSpaceAssociationFile(stateDir string) (SpaceAssociationState, error) {
	payload, err := os.ReadFile(spaceAssociationStatePath(stateDir))
	if err != nil {
		if os.IsNotExist(err) {
			return SpaceAssociationState{}, nil
		}
		return SpaceAssociationState{}, fmt.Errorf("hseh association: read: %w", err)
	}
	var state SpaceAssociationState
	if err := json.Unmarshal(payload, &state); err != nil {
		return SpaceAssociationState{}, fmt.Errorf("hseh association: corrupt state: %w", err)
	}
	if state.Records == nil {
		state.Records = []SpaceAssociationRecord{}
	}
	return state, nil
}

func writeSpaceAssociationFile(stateDir string, state SpaceAssociationState) error {
	dir := sessionHistoryDir(stateDir)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("hseh association: mkdir: %w", err)
	}
	payload, err := json.Marshal(state)
	if err != nil {
		return fmt.Errorf("hseh association: encode: %w", err)
	}
	temporaryPath := filepath.Join(dir, fmt.Sprintf("associations.%d.tmp", os.Getpid()))
	if err := os.WriteFile(temporaryPath, append(payload, '\n'), 0o600); err != nil {
		return fmt.Errorf("hseh association: write: %w", err)
	}
	if err := os.Rename(temporaryPath, spaceAssociationStatePath(stateDir)); err != nil {
		_ = os.Remove(temporaryPath)
		return fmt.Errorf("hseh association: rename: %w", err)
	}
	return nil
}

func spaceAssociationWitnessMismatch(state SpaceAssociationState, live ServerContinuityWitness) bool {
	return len(state.Records) > 0 && !sameServerContinuityWitness(state.Witness, live)
}

func loadSpaceAssociationsForSameServer(stateDir string, live ServerContinuityWitness) (SpaceAssociationState, error) {
	state, err := loadSpaceAssociationFile(stateDir)
	if err != nil {
		return SpaceAssociationState{}, err
	}
	if spaceAssociationWitnessMismatch(state, live) {
		return state, errUnresolvedSpaceAssociationRestart
	}
	state.Witness = live
	return state, nil
}

func upsertSpaceAssociation(state SpaceAssociationState, record SpaceAssociationRecord) SpaceAssociationState {
	replaced := false
	for i, existing := range state.Records {
		if existing.DefinitionID == record.DefinitionID && existing.ResolvedDir == record.ResolvedDir {
			state.Records[i] = record
			replaced = true
			break
		}
	}
	if !replaced {
		state.Records = append(state.Records, record)
	}
	return state
}

func liveWorkspaceIDs(snapshot HerdrSessionSnapshot) map[string]bool {
	live := map[string]bool{}
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID != "" {
			live[workspace.WorkspaceID] = true
		}
	}
	return live
}

func workspaceAssociatedToOtherDefinition(state SpaceAssociationState, workspaceID, definitionID, resolvedDir string) bool {
	for _, record := range state.Records {
		if record.WorkspaceID != workspaceID {
			continue
		}
		if record.DefinitionID == definitionID && record.ResolvedDir == resolvedDir {
			continue
		}
		return true
	}
	return false
}

func exactLiveAssociation(state SpaceAssociationState, snapshot HerdrSessionSnapshot, definitionID, resolvedDir string) (string, bool) {
	live := liveWorkspaceIDs(snapshot)
	for _, record := range state.Records {
		if record.DefinitionID == definitionID && record.ResolvedDir == resolvedDir && live[record.WorkspaceID] {
			return record.WorkspaceID, true
		}
	}
	return "", false
}

func associatedLiveDefinitionKeys(state SpaceAssociationState, snapshot HerdrSessionSnapshot) map[string]bool {
	live := liveWorkspaceIDs(snapshot)
	keys := map[string]bool{}
	for _, record := range state.Records {
		if live[record.WorkspaceID] {
			keys[associationIdentityKey(record.DefinitionID, record.ResolvedDir)] = true
		}
	}
	return keys
}

