func parseRecoverArgs(args []string) (definitionID, workspaceID string, create bool, err error) {
	if len(args) == 0 || strings.TrimSpace(args[0]) == "" || strings.HasPrefix(args[0], "-") {
		return "", "", false, fmt.Errorf("hseh recover: definition id is required")
	}
	definitionID = strings.TrimSpace(args[0])
	seenCreate := false
	seenWorkspace := false
	for i := 1; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--create":
			if seenCreate {
				return "", "", false, fmt.Errorf("hseh recover: unknown argument %s", arg)
			}
			seenCreate = true
			create = true
		case arg == "--workspace":
			if seenWorkspace {
				return "", "", false, fmt.Errorf("hseh recover: unknown argument %s", arg)
			}
			if i+1 >= len(args) {
				return "", "", false, fmt.Errorf("hseh recover: --workspace requires a live workspace id")
			}
			i++
			workspaceID = strings.TrimSpace(args[i])
			seenWorkspace = true
		case strings.HasPrefix(arg, "--workspace="):
			if seenWorkspace {
				return "", "", false, fmt.Errorf("hseh recover: unknown argument %s", arg)
			}
			workspaceID = strings.TrimSpace(arg[len("--workspace="):])
			seenWorkspace = true
		default:
			return "", "", false, fmt.Errorf("hseh recover: unknown argument %s", arg)
		}
	}
	if workspaceID == "" {
		seenWorkspace = false
	}
	if seenCreate == seenWorkspace {
		return "", "", false, fmt.Errorf("hseh recover: exactly one of --workspace <live-workspace-id> or --create is required")
	}
	return definitionID, workspaceID, create, nil
}

// RecoverReusableSpace reconnects or creates an identity left unresolved after a Herdr restart.
func RecoverReusableSpace(ctx context.Context, definitionID, workspaceID string, create bool) (SpaceOpenResult, error) {
	definitionID = strings.TrimSpace(definitionID)
	workspaceID = strings.TrimSpace(workspaceID)
	if definitionID == "" {
		return SpaceOpenResult{}, fmt.Errorf("hseh recover: definition id is required")
	}
	if create == (workspaceID != "") {
		return SpaceOpenResult{}, fmt.Errorf("hseh recover: exactly one of --workspace <live-workspace-id> or --create is required")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	var result SpaceOpenResult
	err := withSpaceOpenLock(ctx, func() error {
		var innerErr error
		result, innerErr = recoverReusableSpaceLocked(ctx, definitionID, workspaceID, create)
		return innerErr
	})
	return result, err
}

func recoverReusableSpaceLocked(ctx context.Context, definitionID, workspaceID string, create bool) (SpaceOpenResult, error) {
	if err := ctx.Err(); err != nil {
		return SpaceOpenResult{}, err
	}
	defs, errs := LoadSpaceDefinitions(spaceDefinitionsDir())
	def, ok := findSpaceDefinitionByID(defs, definitionID)
	if !ok {
		if len(errs) > 0 {
			return SpaceOpenResult{}, fmt.Errorf("hseh recover %s: not found (%s)", definitionID, strings.Join(errs, "; "))
		}
		return SpaceOpenResult{}, fmt.Errorf("hseh recover: definition %s not found", definitionID)
	}
	if err := ctx.Err(); err != nil {
		return SpaceOpenResult{}, err
	}
	snapshot, witness, err := LoadHerdrSessionSnapshotContext(ctx)
	if err != nil {
		return SpaceOpenResult{}, err
	}
	stateDir := pluginStateDir()
	state, err := loadReconciledSpaceAssociationState(stateDir, witness)
	if err != nil {
		return SpaceOpenResult{}, err
	}
	if err := ctx.Err(); err != nil {
		return SpaceOpenResult{}, err
	}
	if liveID, exact := exactLiveAssociation(state, snapshot, def.ID, def.ResolvedDir); exact {
		if !create && workspaceID != liveID {
			return SpaceOpenResult{}, fmt.Errorf("hseh recover: definition %s is already associated with %s", def.ID, liveID)
		}
		if err := FocusHerdrWorkspaceContext(ctx, liveID); err != nil {
			return SpaceOpenResult{}, err
		}
		return SpaceOpenResult{Action: spaceOpenActionFocus, WorkspaceID: liveID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
	}
	if !identityHasUnresolvedSpaceAssociation(state, def.ID, def.ResolvedDir) {
		return SpaceOpenResult{}, fmt.Errorf("hseh recover: definition %s does not need recovery", def.ID)
	}
	if create {
		if err := preflightSpaceDefinitionDirs(def); err != nil {
			return SpaceOpenResult{}, err
		}
		if err := ctx.Err(); err != nil {
			return SpaceOpenResult{}, err
		}
		createdID, rootTabID, rootPaneID, err := createHerdrWorkspace(ctx, def.ResolvedDir, def.Name, true)
		if err != nil {
			return SpaceOpenResult{}, fmt.Errorf("hseh recover %s: workspace.create: %w", def.ID, err)
		}
		record := SpaceAssociationRecord{DefinitionID: def.ID, ResolvedDir: def.ResolvedDir, WorkspaceID: createdID}
		if err := persistCreatedAssociation(stateDir, state, record); err != nil {
			return SpaceOpenResult{Action: spaceOpenActionCreate, WorkspaceID: createdID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, fmt.Errorf("hseh recover %s: persist association after workspace.create %s: %w", def.ID, createdID, err)
		}
		submitted, err := layoutReusableSpace(ctx, def, createdID, rootTabID, rootPaneID)
		result := SpaceOpenResult{Action: spaceOpenActionCreate, WorkspaceID: createdID, SubmittedCommands: submitted, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}
		if err != nil {
			return result, err
		}
		return result, nil
	}
	if !liveWorkspaceIDs(snapshot)[workspaceID] {
		return SpaceOpenResult{}, fmt.Errorf("hseh recover: workspace %s is not live", workspaceID)
	}
	if workspaceAssociatedToOtherDefinition(state, workspaceID, def.ID, def.ResolvedDir) {
		return SpaceOpenResult{}, fmt.Errorf("hseh recover: workspace %s is associated with another definition", workspaceID)
	}
	if err := ctx.Err(); err != nil {
		return SpaceOpenResult{}, err
	}
	record := SpaceAssociationRecord{DefinitionID: def.ID, ResolvedDir: def.ResolvedDir, WorkspaceID: workspaceID}
	if err := persistCreatedAssociation(stateDir, state, record); err != nil {
		return SpaceOpenResult{}, fmt.Errorf("hseh recover %s: persist reconnection: %w", def.ID, err)
	}
	if err := FocusHerdrWorkspaceContext(ctx, workspaceID); err != nil {
		return SpaceOpenResult{}, err
	}
	return SpaceOpenResult{Action: spaceOpenActionReconnect, WorkspaceID: workspaceID, DefinitionID: def.ID, ResolvedDir: def.ResolvedDir}, nil
}

func runRecoverReusableSpace(args []string) error {
	definitionID, workspaceID, create, err := parseRecoverArgs(args)
	if err != nil {
		return err
	}
	result, err := RecoverReusableSpace(context.Background(), definitionID, workspaceID, create)
	if err != nil {
		return err
	}
	fmt.Printf("recovered %s %s %s\n", result.Action, result.DefinitionID, result.WorkspaceID)
	return nil
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// SpaceAssociationRecord is one definition-id + resolved-dir to live workspace link.
type SpaceAssociationRecord struct {
	DefinitionID string `json:"definition_id"`
	ResolvedDir  string `json:"resolved_dir"`
	WorkspaceID  string `json:"workspace_id"`
}

// SpaceAssociationState is session-scoped association provenance for one proven server.
// Unresolved holds identities from earlier server generations that need explicit recovery.
type SpaceAssociationState struct {
	Witness    ServerContinuityWitness  `json:"witness"`
	Records    []SpaceAssociationRecord `json:"records"`
	Unresolved []SpaceAssociationRecord `json:"unresolved"`
}

func spaceAssociationStatePath(stateDir string) string {
	return filepath.Join(sessionHistoryDir(stateDir), "associations.json")
}

func spaceOpenLockPath(stateDir string) string {
	return filepath.Join(sessionHistoryDir(stateDir), "space-open.lock")
}

func associationIdentityKey(definitionID, resolvedDir string) string {
	return definitionID + "\n" + resolvedDir
}

func loadSpaceAssociationFile(stateDir string) (SpaceAssociationState, error) {
	payload, err := os.ReadFile(spaceAssociationStatePath(stateDir))
	if err != nil {
		if os.IsNotExist(err) {
			return SpaceAssociationState{}, nil
		}
		return SpaceAssociationState{}, fmt.Errorf("hseh association: read: %w", err)
	}
	var state SpaceAssociationState
	if err := json.Unmarshal(payload, &state); err != nil {
		return SpaceAssociationState{}, fmt.Errorf("hseh association: corrupt state: %w", err)
	}
	if state.Records == nil {
		state.Records = []SpaceAssociationRecord{}
	}
	if state.Unresolved == nil {
		state.Unresolved = []SpaceAssociationRecord{}
	}
	return state, nil
}

func writeSpaceAssociationFile(stateDir string, state SpaceAssociationState) error {
	dir := sessionHistoryDir(stateDir)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("hseh association: mkdir: %w", err)
	}
	payload, err := json.Marshal(state)
	if err != nil {
		return fmt.Errorf("hseh association: encode: %w", err)
	}
	temporaryPath := filepath.Join(dir, fmt.Sprintf("associations.%d.tmp", os.Getpid()))
	if err := os.WriteFile(temporaryPath, append(payload, '\n'), 0o600); err != nil {
		return fmt.Errorf("hseh association: write: %w", err)
	}
	if err := os.Rename(temporaryPath, spaceAssociationStatePath(stateDir)); err != nil {
		_ = os.Remove(temporaryPath)
		return fmt.Errorf("hseh association: rename: %w", err)
	}
	return nil
}

func spaceAssociationWitnessEmpty(witness ServerContinuityWitness) bool {
	return witness.PeerPID == 0 && witness.PeerStartTime == ""
}

func spaceAssociationWitnessMismatch(state SpaceAssociationState, live ServerContinuityWitness) bool {
	if spaceAssociationWitnessEmpty(state.Witness) && len(state.Records) == 0 {
		return false
	}
	return !sameServerContinuityWitness(state.Witness, live)
}

func appendUnresolvedSpaceAssociation(state SpaceAssociationState, record SpaceAssociationRecord) SpaceAssociationState {
	key := associationIdentityKey(record.DefinitionID, record.ResolvedDir)
	for _, existing := range state.Unresolved {
		if associationIdentityKey(existing.DefinitionID, existing.ResolvedDir) == key {
			return state
		}
	}
	state.Unresolved = append(state.Unresolved, record)
	return state
}

func removeUnresolvedSpaceAssociation(state SpaceAssociationState, definitionID, resolvedDir string) SpaceAssociationState {
	key := associationIdentityKey(definitionID, resolvedDir)
	kept := []SpaceAssociationRecord{}
	for _, record := range state.Unresolved {
		if associationIdentityKey(record.DefinitionID, record.ResolvedDir) == key {
			continue
		}
		kept = append(kept, record)
	}
	state.Unresolved = kept
	return state
}

func identityHasUnresolvedSpaceAssociation(state SpaceAssociationState, definitionID, resolvedDir string) bool {
	key := associationIdentityKey(definitionID, resolvedDir)
	for _, record := range state.Unresolved {
		if associationIdentityKey(record.DefinitionID, record.ResolvedDir) == key {
