func (m pickerModel) View() string {
	if m.width == 0 {
		return "hseh"
	}
	headerText := "hseh  " + m.view + "  /" + m.query
	if m.statusErr != "" {
		headerText = "hseh  " + m.view + "  " + m.statusErr
	}
	header := padDisplayWidth(headerText, m.width)
	bodyHeight := m.height - 1
	if bodyHeight < 1 {
		bodyHeight = 1
	}
	listWidth := m.listPaneWidth()
	showPreview := m.wideEnoughForPreview()
	listBody := m.renderList(listWidth, bodyHeight)
	if !showPreview {
		return header + "\n" + listBody
	}
	previewWidth := m.width - listWidth
	if previewWidth < 1 {
		previewWidth = 1
	}
	preview := m.renderPreview(previewWidth, bodyHeight)
	listLines := strings.Split(listBody, "\n")
	prevLines := strings.Split(preview, "\n")
	var lines []string
	for i := 0; i < bodyHeight; i++ {
		left, right := "", ""
		if i < len(listLines) {
			left = listLines[i]
		}
		if i < len(prevLines) {
			right = prevLines[i]
		}
		lines = append(lines, padDisplayWidth(left, listWidth)+padDisplayWidth(right, previewWidth))
	}
	return header + "\n" + strings.Join(lines, "\n")
}

type pickerListLayout struct {
	Lines   []string
	ItemIDs []string
}

func (m pickerModel) listPaneWidth() int {
	if m.wideEnoughForPreview() && m.width > 1 {
		width := m.width / 2
		if width < 1 {
			return 1
		}
		return width
	}
	if m.width < 1 {
		return 1
	}
	return m.width
}

func (m pickerModel) bodyHeight() int {
	h := m.height - 1
	if h < 1 {
		return 1
	}
	return h
}

func (m pickerModel) renderList(width, height int) string {
	layout := m.buildPickerListLayout(width, height)
	return strings.Join(layout.Lines, "\n")
}

func (m pickerModel) buildPickerListLayout(width, height int) pickerListLayout {
	if height < 1 {
		height = 1
	}
	if width < 1 {
		width = 1
	}
	var blocks [][]string
	var blockIDs []string
	var selectedBlock int
	if len(m.visible) == 0 {
		blocks = [][]string{wrapDisplayLine("(no results)", width)}
		blockIDs = []string{""}
	}
	for _, item := range m.visible {
		prefix := "  "
		if item.ID == m.selectedID {
			prefix = "> "
			selectedBlock = len(blocks)
		}
		block := strings.Join(item.DisplayRows, "\n")
		if block == "" {
			block = strings.Join(item.Rows, "\n")
		}
		if block == "" {
			block = item.ID
		}
		var lines []string
		for i, line := range strings.Split(block, "\n") {
			if i == 0 {
				lines = append(lines, wrapDisplayLine(prefix+line, width)...)
			} else {
				lines = append(lines, wrapDisplayLine("  "+line, width)...)
			}
		}
		lines = append(lines, "")
		blocks = append(blocks, lines)
		blockIDs = append(blockIDs, item.ID)
	}
	var all []string
	var allIDs []string
	selectedLine := 0
	lineAt := 0
	for i, block := range blocks {
		if i == selectedBlock {
			selectedLine = lineAt
		}
		id := ""
		if i < len(blockIDs) {
			id = blockIDs[i]
		}
		for _, line := range block {
			all = append(all, line)
			if strings.TrimSpace(line) == "" {
				allIDs = append(allIDs, "")
			} else {
				allIDs = append(allIDs, id)
			}
		}
		lineAt += len(block)
	}
	start := windowAroundStart(len(all), height, selectedLine)
	end := start + height
	if end > len(all) {
		end = len(all)
	}
	if start > len(all) {
		start = len(all)
	}
	visible := append([]string{}, all[start:end]...)
	visibleIDs := append([]string{}, allIDs[start:end]...)
	for i, line := range visible {
		visible[i] = padDisplayWidth(line, width)
	}
	visible = padToHeight(visible, height)
	for len(visibleIDs) < height {
		visibleIDs = append(visibleIDs, "")
	}
	if len(visibleIDs) > height {
		visibleIDs = visibleIDs[:height]
	}
	return pickerListLayout{Lines: visible, ItemIDs: visibleIDs}
}

func (m pickerModel) itemIDAtMouse(x, y int) string {
	if y < 1 {
		return ""
	}
	bodyY := y - 1
	listWidth := m.listPaneWidth()
	if x < 0 || x >= listWidth {
		return ""
	}
	layout := m.buildPickerListLayout(listWidth, m.bodyHeight())
	if bodyY < 0 || bodyY >= len(layout.ItemIDs) {
		return ""
	}
	return layout.ItemIDs[bodyY]
}

func (m pickerModel) renderPreview(width, height int) string {
	text := m.previewText
	if m.previewErr != "" {
		text = m.previewErr
	}
	if text == "" {
		text = "(preview)"
	}
	return clipBlock(text, width, height)
}

func wrapDisplayLine(line string, width int) []string {
	if width <= 0 {
		return []string{line}
	}
	wrapped := ansi.Hardwrap(line, width, false)
	if wrapped == "" {
		return []string{""}
	}
	return strings.Split(wrapped, "\n")
}

func padDisplayWidth(line string, width int) string {
	if width <= 0 {
		return ""
	}
	line = ansi.Truncate(line, width, "")
	return lipgloss.NewStyle().Width(width).MaxHeight(1).Render(line)
}

func windowAroundStart(n, height, selected int) int {
	if height < 1 || n <= height {
		return 0
	}
	if selected < 0 {
		selected = 0
	}
	if selected >= n {
		selected = n - 1
	}
	start := selected
	if start+height > n {
		start = n - height
	}
	if start < 0 {
		start = 0
	}
	if selected >= start+height {
		start = selected - height + 1
	}
	if start < 0 {
		start = 0
	}
	return start
}

func windowAround(lines []string, height, selected int) []string {
	start := windowAroundStart(len(lines), height, selected)
	end := start + height
	if end > len(lines) {
		end = len(lines)
	}
	return lines[start:end]
}

func padToHeight(lines []string, height int) []string {
	for len(lines) < height {
		lines = append(lines, "")
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return lines
}

func clipBlock(text string, width, height int) string {
	if width < 1 {
		width = 1
	}
	if height < 1 {
		height = 1
	}
	var lines []string
	for _, line := range strings.Split(text, "\n") {
		lines = append(lines, wrapDisplayLine(line, width)...)
		if len(lines) >= height {
			break
		}
	}
	for i, line := range lines {
		if i >= height {
			break
		}
		lines[i] = padDisplayWidth(line, width)
	}
	return strings.Join(padToHeight(lines, height), "\n")
}

