package main

import (
 "strings"
 "testing"

 tea "github.com/charmbracelet/bubbletea"
 "github.com/charmbracelet/x/ansi"
)

func TestSelectedBlockHasGrayBackground(t *testing.T) {
 m:=pickerModel{selectedID:"a",visible:[]PickerItem{{ID:"a",DisplayRows:[]string{"\x1b[31malpha\x1b[0m", "detail"}},{ID:"b",Rows:[]string{"beta"}}}}
 lines:=strings.Split(m.renderList(20,6),"\n")
 for _, i:=range []int{0,1} {
  if !strings.Contains(lines[i],"\x1b[48;5;243m") {t.Fatalf("selected row lacks gray background: %q",lines[i])}
  if ansi.StringWidth(lines[i])!=20 {t.Fatalf("selected background width: %q",lines[i])}
 }
 if strings.Contains(StripTerminalControls(strings.Join(lines,"\n")),"> ") {t.Fatal("old pointer remains")}
 if strings.Contains(lines[2],"\x1b[48;5;243m") || strings.Contains(lines[3],"\x1b[48;5;243m") {t.Fatal("highlight leaked beyond selected block")}
}

func TestLivePreviewCropsGridToBottomWithoutReflow(t *testing.T) {
 m:=pickerModel{previewPane:"w1:p1",previewText:"TOP"+strings.Repeat(" ",77)+"\nMIDDLE"+strings.Repeat(" ",74)+"\nLAST"+strings.Repeat(" ",76)+"\n"}
 got:=StripTerminalControls(m.renderPreview(12,2))
 lines:=strings.Split(got,"\n")
 if len(lines)!=2 || !strings.HasPrefix(lines[0],"MIDDLE") || !strings.HasPrefix(lines[1],"LAST") {t.Fatalf("not bottom two source rows: %q",got)}
}

func TestLivePreviewPreservesSGRAcrossClippedRows(t *testing.T) {
 m:=pickerModel{previewPane:"w1:p1",previewText:"\x1b[31mTOP\n中文LAST\n"}
 got:=m.renderPreview(6,1)
 if !strings.Contains(got,"\x1b[31m") || ansi.StringWidth(got)!=6 || !strings.HasSuffix(got,"\x1b[0m") {t.Fatalf("style/cell boundary broken: %q",got)}
 if !strings.HasPrefix(StripTerminalControls(got),"中文LA") {t.Fatalf("wrong crop %q",got)}
}

func TestDefinitionPreviewStillStartsAtTop(t *testing.T) {
 m:=pickerModel{previewText:"definition\nfirst tab\nlast tab"}
 if got:=StripTerminalControls(m.renderPreview(12,2));!strings.Contains(got,"definition") || strings.Contains(got,"last tab") {t.Fatalf("definition was tail-cropped: %q",got)}
}

func TestViewTabsTrackKeyboardCycle(t *testing.T) {
 m:=newPickerModel("spaces",HerdrSessionSnapshot{},emptyFocusHistory(ServerContinuityWitness{}),defaultSidebarLayout(),0,100)
 m.width,m.height=100,8
 for _,want:=range []string{"Spaces","Agents","All","Spaces"} {
  got:=m.View()
  for _,label:=range []string{"Spaces","Agents","All"} {if !strings.Contains(StripTerminalControls(got),label) {t.Fatalf("tab missing %s: %q",label,got)}}
  if !strings.Contains(got,"\x1b[48;5;74m\x1b[30m "+want+" ") {t.Fatalf("active tab not %s: %q",want,got)}
  if m.itemIDAtMouse(0,1)!="" {t.Fatal("search header is clickable result")}
  next,_:=m.Update(tea.KeyMsg{Type:tea.KeyTab});m=next.(pickerModel)
 }
}

