func (c *pickerCancels) replace(slot *context.CancelFunc) context.Context {
	if c == nil {
		return context.Background()
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if *slot != nil {
		(*slot)()
	}
	ctx, cancel := context.WithCancel(context.Background())
	*slot = cancel
	return ctx
}

func (c *pickerCancels) cancelPreview() {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.preview != nil {
		c.preview()
		c.preview = nil
	}
}

func (c *pickerCancels) cancelAll() {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.preview != nil {
		c.preview()
		c.preview = nil
	}
	if c.snapshot != nil {
		c.snapshot()
		c.snapshot = nil
	}
	if c.accept != nil {
		c.accept()
		c.accept = nil
	}
}

