package main

import (
 "os"
 "path/filepath"
 "strings"
)

const pickerMuted = "\x1b[90m"

func pickerStatePrefix(status, mode string) (plain, display string) {
 if status=="" {return "",""}
 icon:=stateIconGlyph(status,mode)
 return icon+" ", stylePlainToken(SidebarToken{Name:"state_icon"},icon,status)+" "
}

func agentHarnessIcon(agent string) string {
 switch agent {
 case "pi", "omp": return "π"
 case "claude", "claude-code": return "✳"
 case "codex": return "◈"
 case "amp": return "ϟ"
 case "gemini", "grok": return "✦"
 default: return "◇"
 }
}

func abbreviatedPickerDirectory(dir string) string {
 if dir=="" {return ""}
 dir=filepath.Clean(dir)
 home,_:=os.UserHomeDir()
 if home!="" && dir==home {return "~"}
 if home!="" && strings.HasPrefix(dir,home+string(filepath.Separator)) {
  relative:=strings.TrimPrefix(dir,home+string(filepath.Separator))
  if filepath.Dir(relative)=="." {return "~/"+relative}
  return "~/…/"+filepath.Base(dir)
 }
 if dir==string(filepath.Separator) {return dir}
 if filepath.IsAbs(dir) {
  if filepath.Dir(dir)==string(filepath.Separator) {return dir}
  return "/…/"+filepath.Base(dir)
 }
 return dir
}

