func renderSpaceSidebarRows(workspace HerdrWorkspaceRow, layout SidebarLayout) (plain, display []string) {
	values := map[string]string{
		"state_text": sanitizeTokenValue(workspace.AgentStatus),
		"workspace":  sanitizeTokenValue(workspace.Label),
	}
	if workspace.AgentStatus != "" {
		values["state_icon"] = stateIconGlyph(workspace.AgentStatus, layout.StatusIndicators)
	}
	for name, token := range workspace.Tokens {
		values["$"+name] = sanitizeTokenValue(token)
	}
	return renderSidebarRows(layout.SpaceRows, values, workspace.AgentStatus)
}

