// OpenHsehPluginPopup asks Herdr to open the hseh popup pane entrypoint.
func OpenHsehPluginPopup(view string) error {
	pluginID := osGetenvPluginID()
	var envelope herdrPluginPaneOpenEnvelope
	_, err := CallHerdrMethod("plugin.pane.open", map[string]any{
		"plugin_id":  pluginID,
		"entrypoint": view,
		"placement":  "popup",
		"width":      "85%",
		"height":     "80%",
		"focus":      true,
	}, &envelope)
	if err != nil {
		return err
	}
	if envelope.Type != "ok" && envelope.Type != "plugin_pane_opened" {
		return fmt.Errorf("hseh launch: unexpected plugin.pane.open type %s", envelope.Type)
	}
	return nil
}

func osGetenvPluginID() string {
	if id := os.Getenv("HERDR_PLUGIN_ID"); id != "" {
		return id
	}
	return "hseh"
}

// ActiveWorkspacePaneID returns the active pane in a workspace's active tab.
func ActiveWorkspacePaneID(snapshot HerdrSessionSnapshot, workspaceID string) string {
	activeTabID := ""
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID == workspaceID {
			activeTabID = workspace.ActiveTabID
			break
		}
	}
	if activeTabID == "" {
		return ""
	}
	for _, layout := range snapshot.Layouts {
		if layout.TabID == activeTabID {
			return layout.FocusedPaneID
		}
	}
	return ""
}

func workspaceByID(snapshot HerdrSessionSnapshot, workspaceID string) (HerdrWorkspaceRow, bool) {
	for _, workspace := range snapshot.Workspaces {
		if workspace.WorkspaceID == workspaceID {
			return workspace, true
		}
	}
	return HerdrWorkspaceRow{}, false
}

func tabByID(snapshot HerdrSessionSnapshot, tabID string) (HerdrTabRow, bool) {
	for _, tab := range snapshot.Tabs {
		if tab.TabID == tabID {
			return tab, true
		}
	}
	return HerdrTabRow{}, false
}

ROWS, COLS = 40, 140
GRAY = (118, 118, 118)
ACTIVE = (95, 175, 215)


def palette(n):
    if n >= 232:
        return (8 + (n-232)*10,) * 3
    if n >= 16:
        n -= 16
        levels = [0, 95, 135, 175, 215, 255]
        return (levels[n//36], levels[n//6 % 6], levels[n % 6])
    return None


class StyledScreen(base.CellScreen):
    def __init__(self):
        super().__init__(ROWS, COLS)
        self.bg = None
        self.backgrounds = [[None]*COLS for _ in range(ROWS)]

    def put(self, ch):
        if 0 <= self.r < self.rows and 0 <= self.c < self.cols:
            self.backgrounds[self.r][self.c] = self.bg
        super().put(ch)

    def feed(self, data):
        for part in re.split(r'(\x1b\[[0-9;?]*[A-Za-z])', data):
            if part.startswith('\x1b[') and part.endswith('m'):
                values = [int(v or 0) for v in part[2:-1].split(';')]
                i = 0
                while i < len(values):
                    n = values[i]
                    if n in (0,49): self.bg = None
                    if n in (38,48) and i+1 < len(values):
                        mode = values[i+1]
                        if mode == 5 and i+2 < len(values):
                            if n == 48: self.bg = palette(values[i+2])
                            i += 2
                        elif mode == 2 and i+4 < len(values):
                            if n == 48: self.bg = tuple(values[i+2:i+5])
                            i += 4
                    i += 1
            else:
                if part.startswith('\x1b[') and part.endswith('J'):
                    self.backgrounds = [[None]*COLS for _ in range(ROWS)]
                super().feed(part)

    def colored_label(self, label, color):
        for row in range(ROWS):
            col = self.row(row).find(label)
            if col >= 0 and all(self.backgrounds[row][c] == color for c in range(col,col+len(label))):
                return row,col
        raise AssertionError(f'{label!r} lacks {color}\n{self.dump()}')

    def png(self, path):
        # PIL is optional and only used to view terminal evidence. It is not an app dependency.
        try:
            from PIL import Image, ImageDraw, ImageFont
        except ImportError:
            return
        font_path = subprocess.check_output(['fc-match','monospace','-f','%{file}'],text=True)
        font = ImageFont.truetype(font_path,14)
        image = Image.new('RGB',(COLS*9,ROWS*20),'black')
        draw = ImageDraw.Draw(image)
        for r in range(ROWS):
            for c in range(COLS):
                bg = self.backgrounds[r][c] or (0,0,0)
                draw.rectangle((c*9,r*20,c*9+8,r*20+19),fill=bg)
                draw.text((c*9,r*20),self.cells[r][c],font=font,fill=(235,235,235) if bg != ACTIVE else (0,0,0))
        image.save(path)


def main():
    plugin = Path(sys.argv[1]).resolve()  # staged manifest + binary; never overwrite installed app
    out = Path(sys.argv[2]).resolve()
    out.mkdir(parents=True,exist_ok=True)
    original_registry = base.sha256(base.USER_PLUGINS)
    iso = Path(tempfile.mkdtemp(prefix='hseh-visual-'))
    env = {k:os.environ[k] for k in ('PATH','LANG') if k in os.environ}
    env.update(HOME=str(iso),XDG_CONFIG_HOME=str(iso/'.config'),XDG_STATE_HOME=str(iso/'.local/state'),XDG_DATA_HOME=str(iso/'.local/share'),XDG_CACHE_HOME=str(iso/'.cache'),TERM='xterm-256color',HERDR_SESSION='hseh-visual')

