func TestNerdFontHarnessIcons(t *testing.T) {
	for agent, want := range map[string]string{
		"pi": "\U000f03ff", "omp": "\U000f03ff",
		"claude": "\U000f06c4", "claude-code": "\U000f06c4",
		"codex": "\U000f06a9", "amp": "\U000f140b",
		"gemini": "\U000f0ae2", "grok": "\U000f0ae2", "other": "\U000f018d",
	} {
		got := agentHarnessIcon(agent)
		if got != want || ansi.StringWidth(got) != 1 {
			t.Errorf("%s icon %q, width %d", agent, got, ansi.StringWidth(got))
		}
	}
}

func TestNerdFontGitIconsInSpaceRows(t *testing.T) {
	workspace := HerdrWorkspaceRow{Label: "Project", AgentStatus: "working"}
	plain, display := renderSpaceSidebarRows(workspace, WorkspaceGit{Branch: "main", Status: "+1"}, defaultSidebarLayout())
	if !strings.Contains(plain[0], "\ue702 Project") || !strings.Contains(plain[0], "\ue725 main +1") {
		t.Fatalf("Git icons missing: %q", plain)
	}
	if ansi.Strip(display[0]) != plain[0] || ansi.StringWidth(pickerGitIcon) != 1 || ansi.StringWidth(pickerGitBranchIcon) != 1 {
		t.Fatalf("Git icon display geometry differs: %q", display)
	}
	plain, _ = renderSpaceSidebarRows(workspace, WorkspaceGit{}, defaultSidebarLayout())
	if strings.Contains(plain[0], pickerGitIcon) || strings.Contains(plain[0], pickerGitBranchIcon) {
		t.Fatalf("non-repository has Git icons: %q", plain)
	}
}

