package main

import (
	"regexp"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"
)

const pickerHeaderRows = 2

const pickerSelectedBackground = "\x1b[48;5;243m"
const pickerActiveTabBackground = "\x1b[48;5;74m"

var pickerSGRPattern = regexp.MustCompile(`\x1b\[[0-9:;]*m`)

func (m pickerModel) renderHeader() string {
	var tabs []string
	for _, tab := range []struct{ view, label string }{
		{pickerViewSpaces, "Spaces"}, {pickerViewAgents, "Agents"}, {pickerViewAll, "All"},
	} {
		label := " " + tab.label + " "
		if tab.view == m.view {
			label = pickerActiveTabBackground + "\x1b[30m" + label + "\x1b[0m"
		}
		tabs = append(tabs, label)
	}
	query := "/" + m.query
	if m.statusErr != "" {
		query = m.statusErr
	}
	return padDisplayWidth(strings.Join(tabs, " "), m.width) + "\x1b[0m\n" + padDisplayWidth(query, m.width)
}

func (m pickerModel) View() string {
	if m.width == 0 {
		return "hseh"
	}
	header := m.renderHeader()
	if m.height > 0 && m.height <= pickerHeaderRows {
		return strings.Join(strings.Split(header, "\n")[:m.height], "\n")
	}
	bodyHeight := m.bodyHeight()
	listWidth := m.listPaneWidth()
	showPreview := m.wideEnoughForPreview()
	listBody := m.renderList(listWidth, bodyHeight)
	if !showPreview {
		return header + "\n" + listBody
	}
	previewWidth := m.width - listWidth
	if previewWidth < 1 {
		previewWidth = 1
	}
	preview := m.renderPreview(previewWidth, bodyHeight)
	listLines := strings.Split(listBody, "\n")
	prevLines := strings.Split(preview, "\n")
	var lines []string
	for i := 0; i < bodyHeight; i++ {
		left, right := "", ""
		if i < len(listLines) {
			left = listLines[i]
		}
		if i < len(prevLines) {
			right = prevLines[i]
		}
		lines = append(lines, padDisplayWidth(left, listWidth)+padDisplayWidth(right, previewWidth))
	}
	return header + "\n" + strings.Join(lines, "\n")
}

type pickerListLayout struct {
	Lines   []string
	ItemIDs []string
}

func (m pickerModel) listPaneWidth() int {
	if m.wideEnoughForPreview() && m.width > 1 {
		width := m.width / 2
		if width < 1 {
			return 1
		}
		return width
	}
	if m.width < 1 {
		return 1
	}
	return m.width
}

func (m pickerModel) bodyHeight() int {
	h := m.height - pickerHeaderRows
	if h < 1 {
		return 1
	}
	return h
}

func (m pickerModel) renderList(width, height int) string {
	layout := m.buildPickerListLayout(width, height)
	return strings.Join(layout.Lines, "\n")
}

func (m pickerModel) buildPickerListLayout(width, height int) pickerListLayout {
	if height < 1 {
		height = 1
	}
	if width < 1 {
		width = 1
	}
	var blocks [][]string
	var blockIDs []string
	var selectedBlock int
	if len(m.visible) == 0 {
		blocks = [][]string{wrapDisplayLine("(no results)", width)}
		blockIDs = []string{""}
	}
	for _, item := range m.visible {
		if item.ID == m.selectedID {
			selectedBlock = len(blocks)
		}
		block := strings.Join(item.DisplayRows, "\n")
		if block == "" {
